content:
\begin{definition}\label{def:1.1}
(Classical complexity benchmark for subgradient schemes.)
A classical worst-case iteration-complexity estimate for subgradient-type schemes for non-smooth convex minimization in the black-box oracle model is of order
\begin{equation}\label{eq:1.1}
O\!\left(\frac{1}{\varepsilon^{2}}\right),
\end{equation}
where \(\varepsilon>0\) is the desired absolute accuracy in objective value.
\end{definition}

\begin{definition}\label{def:1.3}
(Constructive lower-bound illustration in the black-box model.)
In the black-box oracle model for non-smooth convex minimization, the complexity rate suggested by \eqref{eq:1.1} cannot be uniformly improved in the dimension.
A constructive hard instance cited in the paper is
\begin{equation}\label{eq:intro:hard_instance}
\min_{x\in\mathbb{R}^{n}}\left\{\max_{1\le i\le n}x^{(i)}:\ \sum_{i=1}^{n}(x^{(i)})^{2}\le 1\right\},
\end{equation}
which is stated to be difficult for all numerical schemes in the black-box setting.
\end{definition}
(depend on: "Definition 1.1.1")

\begin{definition}\label{def:1.4}
(Complexity benchmark for smooth convex minimization.)
For minimizing a convex function with \(L\)-Lipschitz continuous gradient by an optimal first-order method, the paper cites the iteration complexity estimate
\begin{equation}\label{eq:intro:smooth_complexity}
O\!\left(\sqrt{\frac{L}{\varepsilon}}\right),
\end{equation}
for reaching absolute accuracy \(\varepsilon>0\) in objective value.
\end{definition}

\begin{definition}\label{def:1.8}
(Dual norm.)
Given a norm \(\|\cdot\|\) on \(E\), define the dual norm \(\|\cdot\|_{*}\) on \(E^{*}\) by
\begin{equation}\label{eq:dual_norm_def}
\|s\|_{*}=\max\{\langle s,x\rangle: x\in E,\ \|x\|=1\}.
\end{equation}
\end{definition}
(depend on: "Definition 1.1.4")

\begin{definition}\label{def:1.9}
(Adjoint operator.)
Let \(A:E_1\to E_2^{*}\) be a linear operator. Define the adjoint \(A^{*}:E_2\to E_1^{*}\) by
\begin{equation}\label{eq:adjoint_def}
\langle Ax,u\rangle_{2}=\langle A^{*}u,x\rangle_{1}\qquad \forall x\in E_1,\ \forall u\in E_2.
\end{equation}
\end{definition}
(depend on: "Definition 1.1.4")

\begin{definition}\label{def:1.10}
(Operator norm \(\|A\|_{1,2}\).)
For a linear operator \(A:E_1\to E_2^{*}\), define
\begin{equation}\label{eq:operator_norm_def}
\|A\|_{1,2}=\max\{\langle Ax,u\rangle_2: \|x\|_1=1,\ \|u\|_2=1\}.
\end{equation}
\end{definition}
(depend on: "Definition 1.1.6")

\begin{proposition}\label{prop:1.2}
For any \(u\in E_2\), the adjoint operator satisfies
\begin{equation}\label{eq:1.2}
\|A^{*}u\|_{1,*}\le \|A\|_{1,2}\,\|u\|_{2}.
\end{equation}
\end{proposition}
(depend on: "Definition 1.1.5", "Definition 1.1.7", "Definition 1.1.6")

\begin{definition}\label{def:2.1}
(Main problem.)
Let \(Q_1\) be a bounded closed convex set in a finite-dimensional real vector space \(E_1\), and let \(f:Q_1\to\mathbb{R}\) be continuous and convex.
The main optimization problem is
\begin{equation}\label{eq:2.1}
f^{*}=\min\{f(x):x\in Q_1\}.
\end{equation}
\end{definition}

\begin{definition}\label{def:2.2}
(Explicit max-structure model.)
We say that \(f\) admits an explicit max-structure if there exist:
- a finite-dimensional real vector space \(E_2\),
- a closed convex bounded set \(Q_2\subseteq E_2\),
- a linear operator \(A:E_1\to E_2^{*}\),
- a continuous convex function \(\hat f:Q_1\to\mathbb{R}\), and
- a continuous convex function \(\hat\phi:Q_2\to\mathbb{R}\),

such that for all \(x\in Q_1\),
\begin{equation}\label{eq:2.2}
f(x)=\hat f(x)+\max\{\langle Ax,u\rangle_{2}-\hat\phi(u):u\in Q_2\}.
\end{equation}

(Implicit simplicity assumption.) It is assumed that \(\hat\phi\) and \(Q_2\) are simple enough that the maximization problem in \eqref{eq:2.2} can be solved in closed form.

(Non-uniqueness illustration.) For example, one may take \(Q_2\equiv E_2\equiv E_1^{*}\), \(\hat f\equiv 0\), \(A=I\), and define
\begin{equation}\label{eq:conjugate_representation}
\hat\phi(u)\equiv f^{*}(u)=\max\{\langle u,x\rangle_{1}-f(x):x\in E_1\}.
\end{equation}
\end{definition}
(depend on: "Definition 1.2.1")

\begin{definition}\label{def:2.3}
(Adjoint form.)
Assume \eqref{eq:2.2}. Define \(\phi:Q_2\to\mathbb{R}\) by
\begin{equation}\label{eq:2.3}
\phi(u)=-\hat\phi(u)+\min\{\langle Ax,u\rangle_2+\hat f(x):x\in Q_1\}.
\end{equation}
The associated adjoint optimization problem is
\begin{equation}\label{eq:adjoint_problem}
\max\{\phi(u):u\in Q_2\}.
\end{equation}
\end{definition}
(depend on: "Definition 1.2.2")

\begin{proposition}\label{prop:ex1}
Let \(a_1,\dots,a_m\in E_1^{*}\) and \(b\in\mathbb{R}^{m}\). Define
\begin{equation}\label{eq:ex1:f_def}
f(x)=\max_{1\le j\le m}\bigl|\langle a_j,x\rangle_{1}-b^{(j)}\bigr|.
\end{equation}
Then \(f\) admits representations of the explicit max-structure form \eqref{eq:2.2}. In particular:

1) (Conjugate-style representation.) Taking \(A=I\), \(E_2=E_1^{*}\), one can define \(\hat\phi\) by
\begin{equation}\label{eq:ex1:phi_hat_conjugate_like}
\hat\phi(u)=\min_{s\in\mathbb{R}^{m}}\left\{\sum_{j=1}^{m}s^{(j)}b^{(j)}:\ u=\sum_{j=1}^{m}s^{(j)}a_j,\ \sum_{j=1}^{m}|s^{(j)}|\le 1\right\}.
\end{equation}

2) (\(\mathbb{R}^m\) representation.) One can write
\begin{equation}\label{eq:ex1:Rm_representation}
f(x)=\max_{u\in\mathbb{R}^{m}}\left\{\sum_{j=1}^{m}u^{(j)}\bigl(\langle a_j,x\rangle_{1}-b^{(j)}\bigr):\ \sum_{j=1}^{m}|u^{(j)}|\le 1\right\},
\end{equation}
so that \(E_2=\mathbb{R}^m\), \(Q_2=\{u:\sum_{j=1}^{m}|u^{(j)}|\le 1\}\), and one may take \(\hat f\equiv 0\), \(\hat\phi(u)=\langle b,u\rangle_2\).

3) (Simplex lifting.) Let \(u=(u_1,u_2)\in\mathbb{R}^{2m}\) with \(u\ge 0\) and \(\sum_{j=1}^{m}(u_1^{(j)}+u_2^{(j)})=1\). Then
\begin{equation}\label{eq:ex1:simplex_representation}
f(x)=\max_{u\in\mathbb{R}^{2m}}\left\{\sum_{j=1}^{m}\bigl(u_1^{(j)}-u_2^{(j)}\bigr)\bigl(\langle a_j,x\rangle_{1}-b^{(j)}\bigr):\ \sum_{j=1}^{m}(u_1^{(j)}+u_2^{(j)})=1,\ u\ge 0\right\},
\end{equation}
which yields \(Q_2\) as a simplex and \(\hat\phi\) linear.
\end{proposition}
(depend on: "Definition 1.2.2")

\begin{definition}\label{def:2.4}
(Prox-function and prox-center.)
Let \(Q_2\subseteq E_2\) be closed, convex, and bounded.
A function \(d_2:Q_2\to\mathbb{R}\) is called a prox-function for \(Q_2\) if it is continuous and \(\sigma_2\)-strongly convex on \(Q_2\) for some \(\sigma_2>0\).
A prox-center \(u_0\in Q_2\) is any minimizer
\begin{equation}\label{eq:prox_center_def}
u_0\in\arg\min\{d_2(u):u\in Q_2\}.
\end{equation}
We may normalize \(d_2\) so that \(d_2(u_0)=0\).
\end{definition}
(depend on: "Definition 1.2.2")

\begin{proposition}\label{prop:2.4}
Assume \(d_2\) is \(\sigma_2\)-strongly convex on \(Q_2\), and let \(u_0\in\arg\min_{u\in Q_2} d_2(u)\) be a prox-center normalized by \(d_2(u_0)=0\).
Then for all \(u\in Q_2\),
\begin{equation}\label{eq:2.4}
d_2(u)\ge \frac{1}{2}\sigma_2\,\|u-u_0\|_2^2.
\end{equation}
\end{proposition}
(depend on: "Definition 1.2.4")

\begin{definition}\label{def:2.5}
(Smoothed max-function.)
Let \(\mu>0\). Define
\begin{equation}\label{eq:2.5}
f_\mu(x)=\max\{\langle Ax,u\rangle_2-\hat\phi(u)-\mu d_2(u):u\in Q_2\}.
\end{equation}
Denote by \(u_\mu(x)\in Q_2\) an optimal solution (a maximizer) of \eqref{eq:2.5}.
Since \(d_2\) is strongly convex, the function \(u\mapsto -\hat\phi(u)-\mu d_2(u)\) is strictly concave on \(Q_2\) (using convexity of \(\hat\phi\)), hence the maximizer \(u_\mu(x)\) is unique.
\end{definition}
(depend on: "Definition 1.2.2", "Definition 1.2.4")

\begin{theorem}\label{thm:1}
Assume \(\mu>0\) and that \(d_2\) is \(\sigma_2\)-strongly convex on \(Q_2\). Then \(f_\mu\) defined by \eqref{eq:2.5} is well-defined and continuously differentiable for all \(x\in E_1\). Moreover, \(f_\mu\) is convex and
\begin{equation}\label{eq:2.6}
\nabla f_\mu(x)=A^{*}u_\mu(x).
\end{equation}
The gradient is Lipschitz continuous with constant
\begin{equation}\label{eq:L_mu}
L_\mu=\frac{1}{\mu\sigma_2}\,\|A\|_{1,2}^{2}.
\end{equation}
\end{theorem}
(depend on: "Definition 1.2.5", "Proposition 1.2", "Definition 1.1.6", "Proposition 1.1.1")

proof:
\begin{proof}\label{proof:thm:1}
(Convexity and differentiability.)
For every fixed \(u\in Q_2\), the function
\(x\mapsto \langle Ax,u\rangle_2-\hat\phi(u)-\mu d_2(u)\) is affine (hence convex) in \(x\).
Therefore, the pointwise maximum over \(u\in Q_2\) in \eqref{eq:2.5} is convex.
The maximizer \(u_\mu(x)\) is unique by Definition~\ref{def:2.5}; in this situation the maximum in \eqref{eq:2.5} is differentiable and its gradient equals the coefficient of \(x\) in the unique active affine function, namely \(A^{*}u_\mu(x)\), yielding \eqref{eq:2.6}.

(Lipschitz continuity of the gradient: proof as in the paper.)
Fix two points \(x_1,x_2\in E_1\). For brevity, denote
\(u_1=u_\mu(x_1)\) and \(u_2=u_\mu(x_2)\).
For the sake of notation, as in the paper we assume without loss of generality that \(\hat\phi\) and \(d_2\) are differentiable; otherwise one can write the same argument using subgradients.

Since \(u_1\) maximizes \(u\mapsto \langle Ax_1,u\rangle_2-\hat\phi(u)-\mu d_2(u)\) over the convex set \(Q_2\), the first-order optimality condition gives
\begin{equation}\label{eq:thm1:opt1}
\langle Ax_1-\nabla\hat\phi(u_1)-\mu\nabla d_2(u_1),\ u_2-u_1\rangle_2\le 0.
\end{equation}
Similarly, optimality of \(u_2\) for \(x_2\) yields
\begin{equation}\label{eq:thm1:opt2}
\langle Ax_2-\nabla\hat\phi(u_2)-\mu\nabla d_2(u_2),\ u_1-u_2\rangle_2\le 0.
\end{equation}
Adding \eqref{eq:thm1:opt1} and \eqref{eq:thm1:opt2} and rearranging terms, we obtain
\begin{align}
\label{eq:thm1:add}
\langle A(x_1-x_2),u_1-u_2\rangle_2
&\ge \langle \nabla\hat\phi(u_1)-\nabla\hat\phi(u_2)+\mu(\nabla d_2(u_1)-\nabla d_2(u_2)),\ u_1-u_2\rangle_2.
\end{align}
By convexity of \(\hat\phi\), the gradient is monotone, hence
\begin{equation}\label{eq:thm1:monotone_phi}
\langle \nabla\hat\phi(u_1)-\nabla\hat\phi(u_2),\ u_1-u_2\rangle_2\ge 0.
\end{equation}
By \(\sigma_2\)-strong convexity of \(d_2\) (in the differentiable case), we have the strong monotonicity estimate
\begin{equation}\label{eq:thm1:strong_monotone_d2}
\langle \nabla d_2(u_1)-\nabla d_2(u_2),\ u_1-u_2\rangle_2\ge \sigma_2\,\|u_1-u_2\|_2^2.
\end{equation}
Combining \eqref{eq:thm1:add}, \eqref{eq:thm1:monotone_phi}, and \eqref{eq:thm1:strong_monotone_d2}, we get exactly the inequality chain written in the paper:
\begin{equation}\label{eq:thm1:key}
\langle A(x_1-x_2),u_1-u_2\rangle_2\ge \mu\,\sigma_2\,\|u_1-u_2\|_2^2.
\end{equation}

Now apply Proposition~\ref{prop:1.2} to \(u=u_1-u_2\):
\begin{equation}\label{eq:thm1:Astar_bound}
\|A^{*}(u_1-u_2)\|_{1,*}\le \|A\|_{1,2}\,\|u_1-u_2\|_2.
\end{equation}
Squaring \eqref{eq:thm1:Astar_bound} gives
\begin{equation}\label{eq:thm1:square1}
\|A^{*}(u_1-u_2)\|_{1,*}^{2}\le \|A\|_{1,2}^{2}\,\|u_1-u_2\|_2^{2}.
\end{equation}
Using \eqref{eq:thm1:key} to bound \(\|u_1-u_2\|_2^{2}\) from above yields
\begin{equation}\label{eq:thm1:square2}
\|A^{*}(u_1-u_2)\|_{1,*}^{2}
\le \frac{\|A\|_{1,2}^{2}}{\mu\sigma_2}\,\langle A(x_1-x_2),u_1-u_2\rangle_2.
\end{equation}
Finally, by the adjoint relation \eqref{eq:adjoint_def},
\(\langle A(x_1-x_2),u_1-u_2\rangle_2=\langle A^{*}(u_1-u_2),x_1-x_2\rangle_1\).
Hence, by Cauchy--Schwarz for the dual pairing (i.e. \(\langle s,h\rangle_1\le \|s\|_{1,*}\,\|h\|_1\)), we have
\begin{equation}\label{eq:thm1:CS}
\langle A^{*}(u_1-u_2),x_1-x_2\rangle_1
\le \|A^{*}(u_1-u_2)\|_{1,*}\,\|x_1-x_2\|_1.
\end{equation}
Substituting \eqref{eq:thm1:CS} into \eqref{eq:thm1:square2} yields
\[
\|A^{*}(u_1-u_2)\|_{1,*}^{2}
\le \frac{\|A\|_{1,2}^{2}}{\mu\sigma_2}\,\|A^{*}(u_1-u_2)\|_{1,*}\,\|x_1-x_2\|_1.
\]
If \(\|A^{*}(u_1-u_2)\|_{1,*}=0\), the Lipschitz inequality holds trivially.
Otherwise, cancel one factor \(\|A^{*}(u_1-u_2)\|_{1,*}\) to get
\begin{equation}\label{eq:thm1:lipschitz}
\|A^{*}u_1-A^{*}u_2\|_{1,*}
=\|A^{*}(u_1-u_2)\|_{1,*}
\le \frac{\|A\|_{1,2}^{2}}{\mu\sigma_2}\,\|x_1-x_2\|_1.
\end{equation}
Using \eqref{eq:2.6}, \eqref{eq:thm1:lipschitz} becomes
\(\|\nabla f_\mu(x_1)-\nabla f_\mu(x_2)\|_{1,*}\le L_\mu\,\|x_1-x_2\|_1\)
with \(L_\mu\) given by \eqref{eq:L_mu}. This completes the proof.
\end{proof}

