\begin{proposition}\label{prop:2.7}
Define
\begin{equation}\label{eq:D2_def}
D_2=\max\{d_2(u):u\in Q_2\},
\end{equation}
and
\begin{equation}\label{eq:f0_def}
f_0(x)=\max\{\langle Ax,u\rangle_2-\hat\phi(u):u\in Q_2\}.
\end{equation}
Then for all \(x\in E_1\),
\begin{equation}\label{eq:2.7}
f_\mu(x)\le f_0(x)\le f_\mu(x)+\mu D_2.
\end{equation}
\end{proposition}
(depend on: "Definition 1.2.5", "Definition 1.2.4")

\begin{proposition}\label{prop:3.1}
Let \(Q\subseteq E\) be a closed convex set in a finite-dimensional real normed space \((E,\|\cdot\|)\). Let \(f:Q\to\mathbb{R}\) be convex and differentiable on \(Q\). Assume that the gradient is Lipschitz continuous with constant \(L>0\), namely
\begin{equation}\label{eq:grad_lipschitz}
\|\nabla f(x)-\nabla f(y)\|_{*}\le L\,\|x-y\|\qquad \forall x,y\in Q.
\end{equation}
Then for any \(x,y\in Q\),
\begin{equation}\label{eq:3.1}
f(y)\le f(x)+\langle \nabla f(x),y-x\rangle+\frac{L}{2}\,\|y-x\|^{2}.
\end{equation}
\end{proposition}
(depend on: "Definition 1.1.4", "Definition 1.1.5")

proof:
\begin{proof}\label{proof:prop:3.1}
Fix \(x,y\in Q\) and define \(\gamma(t)=x+t(y-x)\) for \(t\in[0,1]\). Since \(Q\) is convex, \(\gamma(t)\in Q\) for all \(t\in[0,1]\).
Define \(\varphi(t)=f(\gamma(t))\). Then \(\varphi\) is differentiable and
\begin{equation}\label{eq:prop31:phi_prime}
\varphi'(t)=\langle \nabla f(\gamma(t)),y-x\rangle.
\end{equation}
Using the fundamental theorem of calculus,
\begin{equation}\label{eq:prop31:ftc}
f(y)-f(x)=\varphi(1)-\varphi(0)=\int_0^1 \langle \nabla f(\gamma(t)),y-x\rangle\,dt.
\end{equation}
Subtract \(\langle \nabla f(x),y-x\rangle\) from both sides and use \eqref{eq:prop31:ftc}:
\begin{equation}\label{eq:prop31:diff}
f(y)-f(x)-\langle \nabla f(x),y-x\rangle
=\int_0^1 \langle \nabla f(\gamma(t))-\nabla f(x),y-x\rangle\,dt.
\end{equation}
By the duality inequality \(\langle s,h\rangle\le \|s\|_*\,\|h\|\) and \eqref{eq:grad_lipschitz}, we obtain for each \(t\in[0,1]\)
\begin{equation}\label{eq:prop31:bound_pointwise}
\langle \nabla f(\gamma(t))-\nabla f(x),y-x\rangle
\le \|\nabla f(\gamma(t))-\nabla f(x)\|_*\,\|y-x\|
\le L\,\|\gamma(t)-x\|\,\|y-x\|.
\end{equation}
Since \(\gamma(t)-x=t(y-x)\), we have \(\|\gamma(t)-x\|=t\,\|y-x\|\). Substituting into \eqref{eq:prop31:bound_pointwise} gives
\begin{equation}\label{eq:prop31:bound_pointwise2}
\langle \nabla f(\gamma(t))-\nabla f(x),y-x\rangle\le Lt\,\|y-x\|^2.
\end{equation}
Integrating \eqref{eq:prop31:bound_pointwise2} over \([0,1]\) and using \eqref{eq:prop31:diff}, we get
\begin{equation}\label{eq:prop31:integrate}
f(y)-f(x)-\langle \nabla f(x),y-x\rangle\le \int_0^1 Lt\,\|y-x\|^2\,dt=\frac{L}{2}\,\|y-x\|^2.
\end{equation}
Rearranging \eqref{eq:prop31:integrate} yields \eqref{eq:3.1}.
\end{proof}

