\begin{definition}\label{def:3.2}
Let \(f\) satisfy the assumptions of Proposition~\ref{prop:3.1}. For \(x\in Q\), define \(T_Q(x)\in Q\) to be any minimizer of
\begin{equation}\label{eq:3.2}
\min_{y\in Q}\left\{\langle \nabla f(x),y-x\rangle+\frac{L}{2}\,\|y-x\|^2\right\}.
\end{equation}
If the norm \(\|\cdot\|\) is not strictly convex, the minimizer may be non-unique; in that case \(T_Q(x)\) denotes an arbitrary choice of minimizer.
\end{definition}
(depend on: "Proposition 1.3.1")

\begin{proposition}\label{prop:3.3}
Under the assumptions of Proposition~\ref{prop:3.1}, for any \(x\in Q\) we have
\begin{equation}\label{eq:3.3}
f(T_Q(x))\le f(x)+\min_{y\in Q}\left\{\langle \nabla f(x),y-x\rangle+\frac{L}{2}\,\|y-x\|^2\right\}.
\end{equation}
\end{proposition}
(depend on: "Proposition 1.3.1", "Definition 1.3.1")

proof:
\begin{proof}\label{proof:prop:3.3}
Apply Proposition~\ref{prop:3.1} with \(y=T_Q(x)\). This gives
\begin{equation}\label{eq:prop33:apply31}
f(T_Q(x))\le f(x)+\left\langle \nabla f(x),T_Q(x)-x\right\rangle+\frac{L}{2}\,\|T_Q(x)-x\|^2.
\end{equation}
By Definition~\ref{def:3.2}, \(T_Q(x)\) minimizes the expression in \eqref{eq:3.2}, hence
\begin{equation}\label{eq:prop33:minimizer}
\left\langle \nabla f(x),T_Q(x)-x\right\rangle+\frac{L}{2}\,\|T_Q(x)-x\|^2
=\min_{y\in Q}\left\{\langle \nabla f(x),y-x\rangle+\frac{L}{2}\,\|y-x\|^2\right\}.
\end{equation}
Substituting \eqref{eq:prop33:minimizer} into \eqref{eq:prop33:apply31} yields \eqref{eq:3.3}.
\end{proof}

