\begin{definition}\label{def:3.4}
Let \(Q\subseteq E\) be closed and convex. A function \(d:Q\to\mathbb{R}\) is called a prox-function for \(Q\) if it is continuous and \(\sigma\)-strongly convex on \(Q\) for some \(\sigma>0\).
Define the prox-center \(x_0\in Q\) by
\begin{equation}\label{eq:prox_center_3}
x_0\in\arg\min_{x\in Q} d(x).
\end{equation}
Assume the normalization \(d(x_0)=0\).
\end{definition}

\begin{proposition}\label{prop:3.4}
Assume \(d\) is \(\sigma\)-strongly convex on \(Q\) and \(x_0\in\arg\min_{x\in Q} d(x)\) with \(d(x_0)=0\). Then for all \(x\in Q\),
\begin{equation}\label{eq:3.4}
d(x)\ge \frac{\sigma}{2}\,\|x-x_0\|^2.
\end{equation}
\end{proposition}
(depend on: "Definition 1.3.2")

proof:
\begin{proof}\label{proof:prop:3.4}
Fix \(x\in Q\). For any \(t\in(0,1)\), set
\(x_t=(1-t)x_0+t x\). Since \(Q\) is convex, \(x_t\in Q\).
Because \(x_0\) minimizes \(d\) over \(Q\), we have \(d(x_0)\le d(x_t)\).

By \(\sigma\)-strong convexity of \(d\) on \(Q\), for all \(t\in(0,1)\) we have
\begin{equation}\label{eq:prop34:strong_convex}
d(x_t)\le (1-t)d(x_0)+t d(x)-\frac{\sigma}{2}\,t(1-t)\,\|x-x_0\|^2.
\end{equation}
Combining \(d(x_0)\le d(x_t)\) with \eqref{eq:prop34:strong_convex} and rearranging yields
\begin{equation}\label{eq:prop34:at_center}
d(x)\ge d(x_0)+\frac{\sigma}{2}(1-t)\,\|x-x_0\|^2.
\end{equation}
Letting \(t\to 0^+\) gives
\(d(x)\ge d(x_0)+\frac{\sigma}{2}\|x-x_0\|^2\).
Using the normalization \(d(x_0)=0\) yields \eqref{eq:3.4}.
\end{proof}

