\begin{definition}\label{def:3.5}
Consider the smooth convex minimization problem
\begin{equation}\label{eq:3.5}
\min_{x\in Q} f(x),
\end{equation}
where \(Q\subseteq E\) is closed and convex, and \(f\) is convex and differentiable on \(Q\) with \(L\)-Lipschitz continuous gradient as in \eqref{eq:grad_lipschitz}.
\end{definition}
(depend on: "Proposition 1.3.1")

\begin{definition}\label{def:3.6}
Let \(\{\alpha_i\}_{i\ge 0}\) be positive step-size parameters and define
\begin{equation}\label{eq:Ak_def}
A_k=\sum_{i=0}^k \alpha_i.
\end{equation}
Given points \(x_0,\dots,x_k\in Q\), define the function
\begin{equation}\label{eq:psi_k_def}
\psi_k\;=\;\min_{x\in Q}\left\{\frac{L}{\sigma}d(x)+\sum_{i=0}^k \alpha_i\bigl[f(x_i)+\langle \nabla f(x_i),x-x_i\rangle\bigr]\right\}.
\end{equation}
Given a sequence \(\{y_k\}_{k\ge 0}\subseteq Q\), define the relation
\begin{equation}\label{eq:Rk}
(R_k):\qquad A_k f(y_k)\le \psi_k.
\end{equation}
\end{definition}
(depend on: "Definition 1.3.2", "Definition 1.3.3")

\begin{proposition}\label{prop:3.7}
Assume \(\alpha_0\in(0,1]\). Let \(x_0\) be the prox-center of \(Q\) from Definition~\ref{def:3.4}, and set
\begin{equation}\label{eq:y0_def}
y_0=T_Q(x_0).
\end{equation}
Then the relation \((R_0)\) in \eqref{eq:Rk} holds.
\end{proposition}
(depend on: "Definition 1.3.4", "Proposition 1.3.3", "Proposition 1.3.1", "Definition 1.3.1", "Definition 1.3.2")

proof:
\begin{proof}\label{proof:prop:3.7}
By Definition~\ref{def:3.6} with \(k=0\),
\begin{equation}\label{eq:prop37:psi0}
\psi_0=\min_{x\in Q}\left\{\frac{L}{\sigma}d(x)+\alpha_0\bigl[f(x_0)+\langle \nabla f(x_0),x-x_0\rangle\bigr]\right\}.
\end{equation}
By Proposition~\ref{prop:3.4}, \(\frac{L}{\sigma}d(x)\ge \frac{L}{2}\|x-x_0\|^2\) for all \(x\in Q\). Hence
\begin{equation}\label{eq:prop37:lb1}
\psi_0\ge \min_{x\in Q}\left\{\frac{L}{2}\|x-x_0\|^2+\alpha_0\bigl[f(x_0)+\langle \nabla f(x_0),x-x_0\rangle\bigr]\right\}.
\end{equation}
Factor out \(\alpha_0\) to obtain
\begin{equation}\label{eq:prop37:lb2}
\psi_0\ge \alpha_0\min_{x\in Q}\left\{f(x_0)+\langle \nabla f(x_0),x-x_0\rangle+\frac{L}{2\alpha_0}\|x-x_0\|^2\right\}.
\end{equation}
Since \(\alpha_0\le 1\), we have \(\frac{L}{2\alpha_0}\|x-x_0\|^2\ge \frac{L}{2}\|x-x_0\|^2\) for all \(x\in Q\). Therefore
\begin{equation}\label{eq:prop37:lb3}
\min_{x\in Q}\left\{f(x_0)+\langle \nabla f(x_0),x-x_0\rangle+\frac{L}{2\alpha_0}\|x-x_0\|^2\right\}
\ge
\min_{x\in Q}\left\{f(x_0)+\langle \nabla f(x_0),x-x_0\rangle+\frac{L}{2}\|x-x_0\|^2\right\}.
\end{equation}
Let \(y_0=T_Q(x_0)\). By Proposition~\ref{prop:3.1} applied to \(x=x_0\) and \(y=y_0\),
\begin{equation}\label{eq:prop37:apply31}
f(y_0)\le f(x_0)+\langle \nabla f(x_0),y_0-x_0\rangle+\frac{L}{2}\|y_0-x_0\|^2.
\end{equation}
By definition of \(T_Q(x_0)\), the right-hand side of \eqref{eq:prop37:apply31} equals
\(f(x_0)+\min_{x\in Q}\{\langle \nabla f(x_0),x-x_0\rangle+\frac{L}{2}\|x-x_0\|^2\}\).
Thus
\begin{equation}\label{eq:prop37:min_ge}
\min_{x\in Q}\left\{f(x_0)+\langle \nabla f(x_0),x-x_0\rangle+\frac{L}{2}\|x-x_0\|^2\right\}\ge f(y_0).
\end{equation}
Combining \eqref{eq:prop37:lb2}, \eqref{eq:prop37:lb3}, and \eqref{eq:prop37:min_ge} yields \(\psi_0\ge \alpha_0 f(y_0)\). Since \(A_0=\alpha_0\), this is exactly \((R_0)\).
\end{proof}

content:
\begin{definition}\label{def:3.8}
For \(k\ge 0\), define \(z_k\in Q\) to be any minimizer achieving \(\psi_k\) in \eqref{eq:psi_k_def}, namely
\begin{equation}\label{eq:zk_def}
z_k\in\arg\min_{x\in Q}\left\{\frac{L}{\sigma}d(x)+\sum_{i=0}^k \alpha_i\bigl[f(x_i)+\langle \nabla f(x_i),x-x_i\rangle\bigr]\right\}.
\end{equation}
\end{definition}
(depend on: "Definition 1.3.4")

\begin{lemma}\label{lem:1}
Let \(\{\alpha_k\}_{k\ge 0}\) be positive numbers satisfying
\begin{equation}\label{eq:3.6}
\alpha_0\in(0,1],\qquad \alpha_{k+1}^2\le A_{k+1}\ \ \text{for all }k\ge 0,
\end{equation}
where \(A_{k+1}=\sum_{i=0}^{k+1}\alpha_i\). Suppose that \((R_k)\) in \eqref{eq:Rk} holds for some \(k\ge 0\).
Define
\begin{equation}\label{eq:tau_def}
\tau_k=\frac{\alpha_{k+1}}{A_{k+1}},
\end{equation}
and update
\begin{equation}\label{eq:3.7}
x_{k+1}=\tau_k z_k+(1-\tau_k)y_k,\qquad y_{k+1}=T_Q(x_{k+1}).
\end{equation}
Then \((R_{k+1})\) holds.
\end{lemma}
(depend on: "Definition 1.3.4", "Definition 1.3.5", "Definition 1.3.1", "Proposition 1.3.2", "Definition 1.3.2", "Proposition 1.3.1")

proof:
\begin{proof}\label{proof:lem:1}
Assume \((R_k)\) holds.
Define
\begin{equation}\label{eq:Fk_def}
F_k(x)=\frac{L}{\sigma}d(x)+\sum_{i=0}^k \alpha_i\bigl[f(x_i)+\langle \nabla f(x_i),x-x_i\rangle\bigr].
\end{equation}
Then \(\psi_k=\min_{x\in Q}F_k(x)\) and \(z_k\) is a minimizer of \(F_k\) by Definition~\ref{def:3.8}.
Since \(d\) is \(\sigma\)-strongly convex, the function \(\frac{L}{\sigma}d\) is \(L\)-strongly convex. Hence \(F_k\) is \(L\)-strongly convex on \(Q\), and therefore for all \(x\in Q\),
\begin{equation}\label{eq:lem1:strong_lb}
F_k(x)\ge F_k(z_k)+\frac{L}{2}\|x-z_k\|^2=\psi_k+\frac{L}{2}\|x-z_k\|^2.
\end{equation}
Now
\begin{equation}\label{eq:Fk1_def}
F_{k+1}(x)=F_k(x)+\alpha_{k+1}\bigl[f(x_{k+1})+\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle\bigr],
\end{equation}
so using \eqref{eq:lem1:strong_lb} we get
\begin{equation}\label{eq:lem1:psi_k1_lb}
\psi_{k+1}=\min_{x\in Q}F_{k+1}(x)
\ge \min_{x\in Q}\left\{\psi_k+\frac{L}{2}\|x-z_k\|^2+\alpha_{k+1}\bigl[f(x_{k+1})+\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle\bigr]\right\}.
\end{equation}
Using \((R_k)\), we have \(\psi_k\ge A_k f(y_k)\). By convexity of \(f\), for any \(u,v\in Q\),
\begin{equation}\label{eq:lem1:convex_support}
f(u)\ge f(v)+\langle \nabla f(v),u-v\rangle.
\end{equation}
Apply \eqref{eq:lem1:convex_support} with \(u=y_k\) and \(v=x_{k+1}\), and multiply by \(A_k\), obtaining
\begin{equation}\label{eq:lem1:Akfy}
A_k f(y_k)\ge A_k\bigl[f(x_{k+1})+\langle \nabla f(x_{k+1}),y_k-x_{k+1}\rangle\bigr].
\end{equation}
Therefore, for all \(x\in Q\),
\begin{align}
\label{eq:3.8}
\psi_k+\alpha_{k+1}\bigl[f(x_{k+1})+\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle\bigr]
&\ge A_k f(y_k)+\alpha_{k+1}\bigl[f(x_{k+1})+\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle\bigr]\\
&\ge A_k\bigl[f(x_{k+1})+\langle \nabla f(x_{k+1}),y_k-x_{k+1}\rangle\bigr]
+\alpha_{k+1}\bigl[f(x_{k+1})+\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle\bigr]\\
&=A_{k+1}f(x_{k+1})+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-z_k\rangle.
\end{align}
Substitute \eqref{eq:3.8} into \eqref{eq:lem1:psi_k1_lb}:
\begin{equation}\label{eq:lem1:psi_k1_lb2}
\psi_{k+1}\ge \min_{x\in Q}\left\{A_{k+1}f(x_{k+1})+\frac{L}{2}\|x-z_k\|^2+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-z_k\rangle\right\}.
\end{equation}
Rewrite the minimization term by factoring \(A_{k+1}\):
\begin{equation}\label{eq:lem1:factor}
\psi_{k+1}\ge A_{k+1}\left[f(x_{k+1})+\min_{x\in Q}\left\{\frac{L}{2A_{k+1}}\|x-z_k\|^2+\tau_k\langle \nabla f(x_{k+1}),x-z_k\rangle\right\}\right].
\end{equation}
From \eqref{eq:3.6} and \eqref{eq:tau_def},
\begin{equation}\label{eq:lem1:tau_relation}
\tau_k^2=\frac{\alpha_{k+1}^2}{A_{k+1}^2}\le \frac{1}{A_{k+1}}.
\end{equation}
Hence \(\frac{L}{2A_{k+1}}\|x-z_k\|^2\ge \frac{L}{2}\tau_k^2\|x-z_k\|^2\), and therefore
\begin{equation}\label{eq:3.9}
\psi_{k+1}\ge A_{k+1}\left[f(x_{k+1})+\min_{x\in Q}\left\{\frac{L}{2}\tau_k^2\|x-z_k\|^2+\tau_k\langle \nabla f(x_{k+1}),x-z_k\rangle\right\}\right].
\end{equation}
Define, for an arbitrary \(x\in Q\),
\begin{equation}\label{eq:lem1:y_def}
y=\tau_k x+(1-\tau_k)y_k.
\end{equation}
Since \(Q\) is convex and \(\tau_k\in[0,1]\), we have \(y\in Q\). By \eqref{eq:3.7},
\begin{equation}\label{eq:lem1:shift}
y-x_{k+1}=\tau_k(x-z_k).
\end{equation}
Using \eqref{eq:lem1:shift}, for any \(x\in Q\) we have
\begin{equation}\label{eq:lem1:change_var}
\frac{L}{2}\tau_k^2\|x-z_k\|^2+\tau_k\langle \nabla f(x_{k+1}),x-z_k\rangle
=\frac{L}{2}\|y-x_{k+1}\|^2+\langle \nabla f(x_{k+1}),y-x_{k+1}\rangle.
\end{equation}
Therefore
\begin{equation}\label{eq:lem1:min_change}
\min_{x\in Q}\left\{\frac{L}{2}\tau_k^2\|x-z_k\|^2+\tau_k\langle \nabla f(x_{k+1}),x-z_k\rangle\right\}
\ge
\min_{y\in Q}\left\{\frac{L}{2}\|y-x_{k+1}\|^2+\langle \nabla f(x_{k+1}),y-x_{k+1}\rangle\right\}.
\end{equation}
By Definition~\ref{def:3.2}, \(y_{k+1}=T_Q(x_{k+1})\) minimizes the right-hand side of \eqref{eq:lem1:min_change}, hence
\begin{equation}\label{eq:lem1:min_value}
\min_{y\in Q}\left\{\frac{L}{2}\|y-x_{k+1}\|^2+\langle \nabla f(x_{k+1}),y-x_{k+1}\rangle\right\}
=\frac{L}{2}\|y_{k+1}-x_{k+1}\|^2+\langle \nabla f(x_{k+1}),y_{k+1}-x_{k+1}\rangle.
\end{equation}
By Proposition~\ref{prop:3.1} applied to \(x=x_{k+1}\) and \(y=y_{k+1}\),
\begin{equation}\label{eq:lem1:apply31}
\frac{L}{2}\|y_{k+1}-x_{k+1}\|^2+\langle \nabla f(x_{k+1}),y_{k+1}-x_{k+1}\rangle\ge f(y_{k+1})-f(x_{k+1}).
\end{equation}
Combine \eqref{eq:3.9}, \eqref{eq:lem1:min_change}, \eqref{eq:lem1:min_value}, and \eqref{eq:lem1:apply31} to obtain
\begin{equation}\label{eq:lem1:conclude}
\psi_{k+1}\ge A_{k+1}\left[f(x_{k+1})+f(y_{k+1})-f(x_{k+1})\right]=A_{k+1}f(y_{k+1}).
\end{equation}
This is \((R_{k+1})\).
\end{proof}

