\begin{lemma}\label{lem:2}
For \(k\ge 0\), define
\begin{equation}\label{eq:alpha_k_def}
\alpha_k=\frac{k+1}{2}.
\end{equation}
Then
\begin{equation}\label{eq:3.10}
\tau_k=\frac{2}{k+3},\qquad A_k=\frac{(k+1)(k+2)}{4},
\end{equation}
and the conditions \eqref{eq:3.6} are satisfied.
\end{lemma}
(depend on: "Lemma 1.3.1", "Definition 1.3.4")

proof:
\begin{proof}\label{proof:lem:2}
By \eqref{eq:alpha_k_def},
\begin{equation}\label{eq:lem2:Ak}
A_k=\sum_{i=0}^k \frac{i+1}{2}=\frac{1}{2}\sum_{j=1}^{k+1} j=\frac{(k+1)(k+2)}{4}.
\end{equation}
Thus \eqref{eq:3.10} holds. Moreover,
\begin{equation}\label{eq:lem2:tau_sq}
\tau_k^2=\left(\frac{\alpha_{k+1}}{A_{k+1}}\right)^2=\frac{\left(\frac{k+2}{2}\right)^2}{\left(\frac{(k+2)(k+3)}{4}\right)^2}=\frac{4}{(k+3)^2}.
\end{equation}
Also
\begin{equation}\label{eq:lem2:invAk1}
\frac{1}{A_{k+1}}=\frac{4}{(k+2)(k+3)}.
\end{equation}
Since \((k+3)^2\ge (k+2)(k+3)\) for \(k\ge 0\), we have \(\tau_k^2\le 1/A_{k+1}\), which is equivalent to \(\alpha_{k+1}^2\le A_{k+1}\). Also \(\alpha_0=1/2\in(0,1]\). Hence \eqref{eq:3.6} holds.
\end{proof}

