\begin{algorithm}\label{alg:3.11}
Assume \(f\) satisfies \eqref{eq:grad_lipschitz} on \(Q\), and let \(d\) be a prox-function for \(Q\) with parameter \(\sigma\).
Initialize at the prox-center \(x_0\) of \(Q\) and set \(y_0=T_Q(x_0)\).
For \(k\ge 0\), iterate:
\begin{enumerate}
\item Compute \(f(x_k)\) and \(\nabla f(x_k)\).
\item Compute \(y_k=T_Q(x_k)\).
\item Compute
\begin{equation}\label{eq:alg311:zk}
z_k\in\arg\min_{x\in Q}\left\{\frac{L}{\sigma}d(x)+\sum_{i=0}^k \frac{i+1}{2}\bigl[f(x_i)+\langle \nabla f(x_i),x-x_i\rangle\bigr]\right\}.
\end{equation}
\item Set
\begin{equation}\label{eq:3.11}
x_{k+1}=\frac{2}{k+3}z_k+\frac{k+1}{k+3}y_k.
\end{equation}
\end{enumerate}
\end{algorithm}
(depend on: "Lemma 1.3.2", "Definition 1.3.1", "Definition 1.3.2", "Proposition 1.3.1")

\begin{theorem}\label{thm:2}
Let sequences \(\{x_k\}_{k\ge 0}\subseteq Q\) and \(\{y_k\}_{k\ge 0}\subseteq Q\) be generated by Algorithm~\ref{alg:3.11}. Then for any \(k\ge 0\),
\begin{equation}\label{eq:3.12}
\frac{(k+1)(k+2)}{4}\,f(y_k)
\le
\min_{x\in Q}\left\{\frac{L}{\sigma}d(x)+\sum_{i=0}^k \frac{i+1}{2}\bigl[f(x_i)+\langle \nabla f(x_i),x-x_i\rangle\bigr]\right\}.
\end{equation}
Let \(x^*\in\arg\min_{x\in Q} f(x)\). Then
\begin{equation}\label{eq:3.13}
f(y_k)-f(x^*)\le \frac{4L\,d(x^*)}{\sigma (k+1)(k+2)}.
\end{equation}
\end{theorem}
(depend on: "Algorithm 1.3.1", "Lemma 1.3.1", "Lemma 1.3.2", "Definition 1.3.4", "Proposition 1.3.4")

proof:
\begin{proof}\label{proof:thm:2}
Let \(\alpha_k=(k+1)/2\) and \(A_k=(k+1)(k+2)/4\) as in Lemma~\ref{lem:2}. By Proposition~\ref{prop:3.7} we have \((R_0)\). By Lemma~\ref{lem:1}, if \((R_k)\) holds then \((R_{k+1})\) holds for the updates used in Algorithm~\ref{alg:3.11}. Hence \((R_k)\) holds for all \(k\ge 0\).

For each \(k\), \((R_k)\) states that
\begin{equation}\label{eq:thm2:Rk}
A_k f(y_k)\le \psi_k.
\end{equation}
Using the definition \eqref{eq:psi_k_def} with \(\alpha_i=(i+1)/2\) and the identity \(A_k=(k+1)(k+2)/4\), we obtain exactly \eqref{eq:3.12}.

To derive \eqref{eq:3.13}, note that for any \(x\in Q\) and any \(i\), convexity of \(f\) gives
\begin{equation}\label{eq:thm2:convex}
f(x)\ge f(x_i)+\langle \nabla f(x_i),x-x_i\rangle.
\end{equation}
Substituting \(x=x^*\) into \eqref{eq:thm2:convex} yields
\begin{equation}\label{eq:thm2:support_at_xstar}
f(x_i)+\langle \nabla f(x_i),x^*-x_i\rangle\le f(x^*).
\end{equation}
Hence
\begin{equation}\label{eq:thm2:psi_bound}
\psi_k
\le \frac{L}{\sigma}d(x^*)+\sum_{i=0}^k \alpha_i f(x^*)
=\frac{L}{\sigma}d(x^*)+A_k f(x^*).
\end{equation}
Combine \eqref{eq:thm2:Rk} with \eqref{eq:thm2:psi_bound} to get
\begin{equation}\label{eq:thm2:gap}
A_k\bigl(f(y_k)-f(x^*)\bigr)\le \frac{L}{\sigma}d(x^*).
\end{equation}
Divide by \(A_k=(k+1)(k+2)/4\) to obtain \eqref{eq:3.13}.
\end{proof}

