\begin{definition}\label{def:3.14}
Define a modified selection rule for \(y_k\) as follows. Given \(y_{k-1}\), compute
\begin{equation}\label{eq:3.14}
\tilde y_k=T_Q(x_k),\qquad y_k\in\arg\min\{f(x):x\in\{y_{k-1},x_k,\tilde y_k\}\}.
\end{equation}
\end{definition}
(depend on: "Definition 1.3.1", "Algorithm 1.3.1")

\begin{proposition}\label{prop:3.15}
If \(\{y_k\}\) is chosen by the rule \eqref{eq:3.14}, then
\begin{equation}\label{eq:3.15}
f(y_k)\le f(y_{k-1})\le\cdots\le f(x_0).
\end{equation}
\end{proposition}
(depend on: "Definition 1.3.6")

proof:
\begin{proof}\label{proof:prop:3.15}
By \eqref{eq:3.14}, the point \(y_k\) is chosen from the set \(\{y_{k-1},x_k,\tilde y_k\}\) to minimize \(f\) on that set. Hence \(f(y_k)\le f(y_{k-1})\). Iterating this inequality over \(k\) yields \eqref{eq:3.15}.
\end{proof}

