\begin{definition}\label{def:4.1}
Assume that $\hat f:Q_1\to\mathbb{R}$ is convex and continuously differentiable, and that its gradient is Lipschitz continuous on $Q_1$ with some constant $M\ge 0$ in the norm $\|\cdot\|_1$:
\begin{equation}\label{eq:auto_Definition_4_1_content_1}
\|\nabla \hat f(x)-\nabla \hat f(y)\|_{1,*}\le M\|x-y\|_1 \quad \forall x,y\in Q_1.
\end{equation}
Let $f_\mu$ be the smoothed function defined in \eqref{eq:2.5}. Define the smoothed objective
\begin{equation}\label{eq:4.1}
\bar f_\mu(x) := \hat f(x) + f_\mu(x),
\qquad\text{and consider}\qquad
\min_{x\in Q_1}\ \bar f_\mu(x).
\tag{4.1}
\end{equation}
\end{definition}
(depend on: "Definition 1.2.5")

\begin{proposition}\label{prop:4.2}
Under the assumptions of Definition 4.1, the function $\bar f_\mu$ has Lipschitz continuous gradient on $Q_1$ with Lipschitz constant
\begin{equation}\label{eq:4.2_Lmu}
L_\mu := M + \frac{1}{\mu\sigma_2}\|A\|_{1,2}^2,
\end{equation}
where $\sigma_2$ is the strong convexity parameter of the prox-function $d_2$ on $Q_2$.
\end{proposition}
(depend on: "Definition 1.4.1", "Theorem 1")

proof:
\begin{proof}\label{proof:prop:4.2}
For any $x,y\in Q_1$,
\begin{equation}\label{eq:auto_Proposition_4_2_proof_1}
\|\nabla \bar f_\mu(x)-\nabla \bar f_\mu(y)\|_{1,*}
\le \|\nabla \hat f(x)-\nabla \hat f(y)\|_{1,*} + \|\nabla f_\mu(x)-\nabla f_\mu(y)\|_{1,*}.
\end{equation}
By the assumption of Definition 4.1, the first term is bounded by $M\|x-y\|_1$.
By Theorem~1, $\nabla f_\mu$ is Lipschitz continuous with constant $\frac{1}{\mu\sigma_2}\|A\|_{1,2}^2$, hence the second term is bounded by $\frac{1}{\mu\sigma_2}\|A\|_{1,2}^2\|x-y\|_1$.
Combining the two bounds yields \eqref{eq:4.2_Lmu}.
\end{proof}

