\begin{definition}\label{def:4.3}
Let $Q_1\subseteq E_1$ be a bounded closed convex set, and let $d_1:Q_1\to\mathbb{R}$ be a prox-function of $Q_1$, meaning that $d_1$ is continuous and $\sigma_1$-strongly convex on $Q_1$ for some $\sigma_1>0$ with respect to $\|\cdot\|_1$.
Assume the (finite) prox-diameter bound $D_1$ satisfies
\begin{equation}\label{eq:4.3_D1}
\max_{x\in Q_1} d_1(x) \;\le\; D_1 \;<\; +\infty.
\end{equation}
\end{definition}
(depend on: "Definition 1.3.5")

\begin{theorem}\label{thm:3}
Assume the structural model \eqref{eq:2.2} and that $\hat f$ in \eqref{eq:2.2} is differentiable with $M$-Lipschitz continuous gradient on $Q_1$.
Let $d_1$ be a prox-function of $Q_1$ with parameter $\sigma_1>0$ and prox-diameter $D_1$ as in \eqref{eq:4.3_D1}.
Let $d_2$ be a prox-function of $Q_2$ with strong convexity parameter $\sigma_2>0$ and define $D_2:=\max_{u\in Q_2} d_2(u)$ as in Proposition~2.7.
Apply Algorithm~3.11 to the smoothed problem \eqref{eq:4.1} with the smoothness parameter
\begin{equation}\label{eq:thm3_muN}
\mu=\mu(N):=\frac{2\|A\|_{1,2}}{N+1}\sqrt{\frac{D_1}{\sigma_1\sigma_2 D_2}}.
\end{equation}
After $N$ iterations, define
\begin{equation}\label{eq:4.2}
\hat x := y_N \in Q_1,
\qquad
\hat u := \sum_{i=0}^{N} \frac{2(i+1)}{(N+1)(N+2)}\,u_\mu(x_i)\in Q_2.
\tag{4.2}
\end{equation}
Then $\hat x$ and $\hat u$ are approximate solutions to the primal problem \eqref{eq:2.1} and the adjoint problem \eqref{eq:2.3} and satisfy the duality-gap estimate
\begin{equation}\label{eq:4.3}
0 \le f(\hat x)-\phi(\hat u)\le
\frac{4\|A\|_{1,2}}{N+1}\sqrt{\frac{D_1D_2}{\sigma_1\sigma_2}}
+\frac{4MD_1}{\sigma_1(N+1)^2}.
\tag{4.3}
\end{equation}
Consequently, the number of iterations sufficient to produce an $\varepsilon$-solution in the sense $f(\hat x)-\phi(\hat u)\le\varepsilon$ satisfies the bound
\begin{equation}\label{eq:4.4}
N \;\le\;
\frac{4\|A\|_{1,2}}{\varepsilon}\sqrt{\frac{D_1D_2}{\sigma_1\sigma_2}}
+2\sqrt{\frac{MD_1}{\sigma_1\varepsilon}}.
\tag{4.4}
\end{equation}
\end{theorem}
(depend on: "Definition 1.4.1", "Proposition 1.4.1", "Definition 1.4.2", "Theorem 2", "Theorem 1", "Proposition 2.7", "Algorithm 3.11", "Definition 1.2.2", "Definition 1.2.1", "Definition 1.2.3", "Proposition 1.2.3")

proof:
\begin{proof}\label{proof:thm:3}
Fix an arbitrary $\mu>0$.
Apply Theorem~2 to the problem \eqref{eq:4.1} with $L=L_\mu$ and prox-function $d_1$.
After $N$ iterations, we obtain $\hat x=y_N$ such that
\begin{equation}\label{eq:4.5}
\bar f_\mu(\hat x)\le
\frac{L_\mu D_1}{\sigma_1(N+1)^2}
+
\min_{x\in Q_1}
\sum_{i=0}^{N}\frac{2(i+1)}{(N+1)(N+2)}
\bigl[\bar f_\mu(x_i)+\langle \nabla \bar f_\mu(x_i),x-x_i\rangle_1\bigr].
\tag{4.5}
\end{equation}

For each $x\in E_1$, by definition of $f_\mu$ and the maximizer $u_\mu(x)$,
\begin{align}
f_\mu(x)
&=\max_{u\in Q_2}\{\langle Ax,u\rangle_2-\hat\phi(u)-\mu d_2(u)\}\label{eq:thm3_fmu_def}\\
&=\langle Ax,u_\mu(x)\rangle_2-\hat\phi(u_\mu(x))-\mu d_2(u_\mu(x)).\label{eq:thm3_fmu_at_um}
\end{align}
Moreover, by Theorem~1,
\begin{equation}\label{eq:thm3_grad_fmu}
\langle \nabla f_\mu(x),x\rangle_1=\langle A^\ast u_\mu(x),x\rangle_1.
\end{equation}
Therefore, for each $i=0,\dots,N$,
\begin{equation}\label{eq:4.6}
f_\mu(x_i)-\langle \nabla f_\mu(x_i),x_i\rangle_1
=-\hat\phi(u_\mu(x_i))-\mu d_2(u_\mu(x_i)).
\tag{4.6}
\end{equation}

Let $\hat u$ be the convex combination defined in \eqref{eq:4.2}. Since $Q_2$ is convex, we indeed have $\hat u\in Q_2$.
Using \eqref{eq:4.6} and the convexity of $\hat f$, we estimate, for any $x\in Q_1$,
\begin{align}
&\sum_{i=0}^{N}(i+1)\bigl[\bar f_\mu(x_i)+\langle \nabla \bar f_\mu(x_i),x-x_i\rangle_1\bigr]\nonumber\\
&\le
\sum_{i=0}^{N}(i+1)\bigl[f_\mu(x_i)-\langle \nabla f_\mu(x_i),x_i\rangle_1\bigr]
+\frac{(N+1)(N+2)}{2}\bigl[\hat f(x)+\langle A^\ast \hat u,x\rangle_1\bigr]\label{eq:thm3_sum_bound1}\\
&\le
-\sum_{i=0}^{N}(i+1)\hat\phi(u_\mu(x_i))
+\frac{(N+1)(N+2)}{2}\bigl[\hat f(x)+\langle A^\ast \hat u,x\rangle_1\bigr]\label{eq:thm3_sum_bound2}\\
&\le
\frac{(N+1)(N+2)}{2}\bigl[-\hat\phi(\hat u)+\hat f(x)+\langle Ax,\hat u\rangle_2\bigr].\label{eq:thm3_sum_bound3}
\end{align}
In the last step we used the convexity of $\hat\phi$ and $d_2$ together with the definition of $\hat u$ as an average.

Substituting \eqref{eq:thm3_sum_bound3} into \eqref{eq:4.5} and using the adjoint definition \eqref{eq:2.3}, we obtain
\begin{equation}\label{eq:auto_Theorem_3_proof_1}
\frac{L_\mu D_1}{\sigma_1(N+1)^2}
\ge
\bar f_\mu(\hat x)-\phi(\hat u).
\end{equation}
Finally, by the approximation bound \eqref{eq:2.7} we have $f(\hat x)\le \bar f_\mu(\hat x)+\mu D_2$, hence
\begin{equation}\label{eq:4.7}
0\le f(\hat x)-\phi(\hat u)\le
\mu D_2+\frac{4\|A\|_{1,2}^2D_1}{\mu\sigma_1\sigma_2(N+1)^2}
+\frac{4MD_1}{\sigma_1(N+1)^2}.
\tag{4.7}
\end{equation}

Minimizing the right-hand side of \eqref{eq:4.7} over $\mu>0$ gives the choice \eqref{eq:thm3_muN} and yields the bound \eqref{eq:4.3}.

To obtain \eqref{eq:4.4}, it suffices to choose $N$ such that the two terms in the right-hand side of \eqref{eq:4.3} are each at most $\varepsilon/2$ and solve the resulting inequalities for $N$.
\end{proof}

content:
\begin{proposition}\label{prop:4.4}
Assume $M=0$ in Theorem~3. An optimal (order-wise) choice of the smoothing parameter $\mu$, the corresponding Lipschitz constant $L_\mu$, and the iteration count $N$ as a function of accuracy $\varepsilon>0$ is
\begin{equation}\label{eq:4.8}
\mu=\frac{\varepsilon}{2D_2},
\qquad
L_\mu=\frac{D_2}{2\sigma_2}\cdot\frac{\|A\|_{1,2}^2}{\varepsilon},
\qquad
N+1=\frac{4\|A\|_{1,2}}{\varepsilon}\sqrt{\frac{D_1D_2}{\sigma_1\sigma_2}}.
\tag{4.8}
\end{equation}
\end{proposition}
(depend on: "Theorem 1.4.1", "Proposition 1.4.1")

proof:
\begin{proof}\label{proof:prop:4.4}
When $M=0$, the bound \eqref{eq:4.7} becomes
\begin{equation}\label{eq:auto_Proposition_4_4_proof_1}
f(\hat x)-\phi(\hat u)\le \mu D_2+\frac{4\|A\|_{1,2}^2D_1}{\mu\sigma_1\sigma_2(N+1)^2}.
\end{equation}
Choose $\mu$ so that the smoothing error term satisfies $\mu D_2=\varepsilon/2$, namely $\mu=\varepsilon/(2D_2)$.
With this choice, enforce the remaining term to be at most $\varepsilon/2$, which is achieved by
\begin{equation}\label{eq:auto_Proposition_4_4_proof_2}
\frac{4\|A\|_{1,2}^2D_1}{\mu\sigma_1\sigma_2(N+1)^2}\le\frac{\varepsilon}{2}.
\end{equation}
Substituting $\mu=\varepsilon/(2D_2)$ and solving for $N$ gives the value of $N+1$ in \eqref{eq:4.8}.
Finally, for $M=0$, Proposition~4.2 gives $L_\mu=\frac{1}{\mu\sigma_2}\|A\|_{1,2}^2$, and substituting $\mu=\varepsilon/(2D_2)$ yields the stated expression for $L_\mu$.
\end{proof}

