\begin{definition}\label{def:4.5}
Define the standard simplex in $\mathbb{R}^n$ by
\begin{equation}\label{eq:Delta_n}
\Delta_n := \Bigl\{x\in\mathbb{R}^n: x^{(i)}\ge 0\ \forall i,\ \sum_{i=1}^n x^{(i)}=1\Bigr\}.
\end{equation}
Let $A:\mathbb{R}^n\to\mathbb{R}^m$, and let $c\in\mathbb{R}^n$, $b\in\mathbb{R}^m$.
Consider the matrix-game saddle-point problem
\begin{equation}\label{eq:4.9}
\min_{x\in\Delta_n}\ \max_{u\in\Delta_m}\ \bigl\{\langle Ax,u\rangle_2+\langle c,x\rangle_1+\langle b,u\rangle_2\bigr\}.
\tag{4.9}
\end{equation}
\end{definition}

\begin{definition}\label{def:4.6}
Let $a_j\in\mathbb{R}^n$ denote the rows of $A$ and $\hat a_i\in\mathbb{R}^m$ denote the columns of $A$.
The saddle-point problem \eqref{eq:4.9} is equivalent to the pair of optimization problems
\begin{equation}\label{eq:4.10}
\min_{x\in\Delta_n}\ f(x),
\qquad
f(x):=\langle c,x\rangle_1+\max_{1\le j\le m}\bigl[\langle a_j,x\rangle_1+b^{(j)}\bigr],
\end{equation}
and
\begin{equation}\label{eq:4.10_dual}
\max_{u\in\Delta_m}\ \phi(u),
\qquad
\phi(u):=\langle b,u\rangle_2+\min_{1\le i\le n}\bigl[\langle \hat a_i,u\rangle_2+c^{(i)}\bigr].
\tag{4.10}
\end{equation}
\end{definition}
(depend on: "Definition 1.4.1.1")

\begin{proposition}\label{prop:4.7}
In the setting of Definition 4.6, choose the Euclidean norms on $\mathbb{R}^n$ and $\mathbb{R}^m$,
\begin{equation}\label{eq:auto_Proposition_4_7_content_1}
\|x\|_1:=\Bigl(\sum_{i=1}^n (x^{(i)})^2\Bigr)^{1/2},
\qquad
\|u\|_2:=\Bigl(\sum_{j=1}^m (u^{(j)})^2\Bigr)^{1/2},
\end{equation}
and the prox-functions on $\Delta_n$ and $\Delta_m$,
\begin{equation}\label{eq:auto_Proposition_4_7_content_2}
d_1(x):=\frac12\sum_{i=1}^n\Bigl(x^{(i)}-\frac1n\Bigr)^2,
\qquad
d_2(u):=\frac12\sum_{j=1}^m\Bigl(u^{(j)}-\frac1m\Bigr)^2.
\end{equation}
Then $\sigma_1=\sigma_2=1$, $D_1=1-\frac1n<1$, $D_2=1-\frac1m<1$, and
\begin{equation}\label{eq:auto_Proposition_4_7_content_3}
\|A\|_{1,2}=\max_{\|x\|_1=1}\|Ax\|_{2}=\lambda_{\max}^{1/2}(A^\top A).
\end{equation}
Moreover, since $\hat f(x)=\langle c,x\rangle_1$ is linear, we have $M=0$, and Theorem~3 yields the bound
\begin{equation}\label{eq:4.11}
0\le f(\hat x)-\phi(\hat u)\le \frac{4\,\lambda_{\max}^{1/2}(A^\top A)}{N+1}.
\tag{4.11}
\end{equation}
\end{proposition}
(depend on: "Theorem 1.4.1", "Definition 1.4.1.2")

proof:
\begin{proof}\label{proof:prop:4.7}
The strong convexity parameters are $\sigma_1=\sigma_2=1$ because $d_1$ and $d_2$ are quadratic functions with Hessian equal to the identity on the ambient Euclidean spaces.
Since $\Delta_n$ and $\Delta_m$ are compact, the prox-diameters are finite; in particular one may take $D_1=1-\frac1n$ and $D_2=1-\frac1m$.
With Euclidean norms, the operator norm is the spectral norm:
\begin{equation}\label{eq:auto_Proposition_4_7_proof_1}
\|A\|_{1,2}=\max_{\|x\|_2=1}\|Ax\|_2=\sqrt{\lambda_{\max}(A^\top A)}.
\end{equation}
Finally, in \eqref{eq:4.3} of Theorem~3 we have $M=0$, $\sigma_1=\sigma_2=1$ and $D_1,D_2<1$, hence
\begin{equation}\label{eq:auto_Proposition_4_7_proof_2}
f(\hat x)-\phi(\hat u)\le \frac{4\|A\|_{1,2}}{N+1}
\le \frac{4\lambda_{\max}^{1/2}(A^\top A)}{N+1},
\end{equation}
which is \eqref{eq:4.11}.
\end{proof}

