\begin{lemma}\label{lem:3}
In the setting of Definition 4.6, choose the $\ell_1$ norms on $\mathbb{R}^n$ and $\mathbb{R}^m$,
\begin{equation}\label{eq:auto_Lemma_3_content_1}
\|x\|_1:=\sum_{i=1}^n |x^{(i)}|,
\qquad
\|u\|_2:=\sum_{j=1}^m |u^{(j)}|,
\end{equation}
and the entropy prox-functions on $\Delta_n$ and $\Delta_m$,
\begin{equation}\label{eq:auto_Lemma_3_content_2}
d_1(x):=\ln n+\sum_{i=1}^n x^{(i)}\ln x^{(i)},
\qquad
d_2(u):=\ln m+\sum_{j=1}^m u^{(j)}\ln u^{(j)}.
\end{equation}
Then the strong convexity parameters and prox-diameters satisfy
\begin{equation}\label{eq:auto_Lemma_3_content_3}
\sigma_1=\sigma_2=1,
\qquad
D_1=\ln n,
\qquad
D_2=\ln m.
\end{equation}
\end{lemma}
(depend on: "Definition 1.4.1.2")

proof:
\begin{proof}\label{proof:lem:3}
The function $d_1$ is twice continuously differentiable on the relative interior of $\Delta_n$ and its Hessian is diagonal:
\begin{equation}\label{eq:auto_Lemma_3_proof_1}
\langle d_1''(x)h,h\rangle=\sum_{i=1}^n \frac{(h^{(i)})^2}{x^{(i)}}.
\end{equation}
For $x$ with positive components, the following variant of the Cauchy--Schwarz inequality holds:
\begin{equation}\label{eq:lem3_cs}
\Bigl(\sum_{i=1}^n |h^{(i)}|\Bigr)^2
\le
\Bigl(\sum_{i=1}^n x^{(i)}\Bigr)\Bigl(\sum_{i=1}^n \frac{(h^{(i)})^2}{x^{(i)}}\Bigr).
\end{equation}
Since $\sum_i x^{(i)}=1$ for $x\in\Delta_n$, \eqref{eq:lem3_cs} implies
\begin{equation}\label{eq:auto_Lemma_3_proof_2}
\langle d_1''(x)h,h\rangle\ge \Bigl(\sum_{i=1}^n |h^{(i)}|\Bigr)^2=\|h\|_1^2,
\end{equation}
which is the strong convexity condition with parameter $\sigma_1=1$ for the $\ell_1$ norm.
The same reasoning applies to $d_2$ on $\Delta_m$ and yields $\sigma_2=1$.

For $x\in\Delta_n$, we have $\sum_i x^{(i)}\ln x^{(i)}\le 0$ and equality holds at the vertices; thus
\begin{equation}\label{eq:auto_Lemma_3_proof_3}
\max_{x\in\Delta_n} d_1(x)=\ln n+\max_{x\in\Delta_n}\sum_i x^{(i)}\ln x^{(i)}=\ln n.
\end{equation}
Similarly, $\max_{u\in\Delta_m} d_2(u)=\ln m$.
\end{proof}

content:
\begin{proposition}\label{prop:4.8}
Under the entropy-distance setup of Lemma~3, the operator norm of $A$ satisfies
\begin{equation}\label{eq:opnorm_entropy}
\|A\|_{1,2}
=\max_{\|x\|_1=1}\|Ax\|_{2,*}
=\max_{i,j}|A^{(i,j)}|.
\end{equation}
Consequently, since $M=0$ for the linear term $\hat f(x)=\langle c,x\rangle_1$, the estimate \eqref{eq:4.3} of Theorem~3 becomes
\begin{equation}\label{eq:4.12}
0\le f(\hat x)-\phi(\hat u)\le
\frac{4\sqrt{\ln n\,\ln m}}{N+1}\cdot \max_{i,j}|A^{(i,j)}|.
\tag{4.12}
\end{equation}
\end{proposition}
(depend on: "Lemma 1.4.1.1", "Theorem 1.4.1")

proof:
\begin{proof}\label{proof:prop:4.8}
For the $\ell_1$ norms, the dual norms are $\ell_\infty$. Hence
\begin{equation}\label{eq:auto_Proposition_4_8_proof_1}
\|A\|_{1,2}=\max_{\|x\|_1=1}\|Ax\|_\infty
=\max_{1\le j\le m}\ \max_{\|x\|_1=1} |\langle a_j,x\rangle_1|
=\max_{1\le j\le m}\ \|a_j\|_\infty
=\max_{i,j}|A^{(i,j)}|.
\end{equation}
With Lemma~3 we have $\sigma_1=\sigma_2=1$, $D_1=\ln n$, $D_2=\ln m$, and $M=0$. Substituting these values into \eqref{eq:4.3} yields \eqref{eq:4.12}.
\end{proof}

