\begin{lemma}\label{lem:4}
Let $\mu>0$ and $s\in\mathbb{R}^m$. Consider the optimization problem
\begin{equation}\label{eq:4.13}
\Phi_\mu(s):=\max_{u\in\Delta_m}\Bigl\{\sum_{j=1}^m u^{(j)}s^{(j)}-\mu\sum_{j=1}^m u^{(j)}\ln u^{(j)}\Bigr\}.
\tag{4.13}
\end{equation}
Then the maximizer is the vector $u_\mu(s)\in\Delta_m$ with entries
\begin{equation}\label{eq:4.14}
u_\mu^{(j)}(s)=\frac{e^{s^{(j)}/\mu}}{\sum_{l=1}^m e^{s^{(l)}/\mu}},\qquad j=1,\dots,m,
\tag{4.14}
\end{equation}
and the optimal value is
\begin{equation}\label{eq:auto_Lemma_4_content_1}
\Phi_\mu(s)=\mu\ln\Bigl(\sum_{j=1}^m e^{s^{(j)}/\mu}\Bigr).
\end{equation}
\end{lemma}

proof:
\begin{proof}\label{proof:lem:4}
The objective in \eqref{eq:4.13} is strictly concave in $u$ on the relative interior of $\Delta_m$, hence the maximizer is characterized by the first-order optimality conditions with a Lagrange multiplier $\lambda$ for the constraint $\sum_j u^{(j)}=1$:
\begin{equation}\label{eq:auto_Lemma_4_proof_1}
s^{(j)}-\mu\bigl(1+\ln u^{(j)}\bigr)=\lambda,\qquad j=1,\dots,m,
\qquad
\sum_{j=1}^m u^{(j)}=1.
\end{equation}
Solving for $u^{(j)}$ gives $u^{(j)}=\exp\bigl((s^{(j)}-\lambda-\mu)/\mu\bigr)$.
Imposing $\sum_j u^{(j)}=1$ yields
\begin{equation}\label{eq:auto_Lemma_4_proof_2}
e^{-(\lambda+\mu)/\mu}\sum_{j=1}^m e^{s^{(j)}/\mu}=1,
\qquad\text{so}\qquad
\lambda=\mu\ln\Bigl(\sum_{j=1}^m e^{s^{(j)}/\mu}\Bigr)-\mu.
\end{equation}
Substituting this back gives \eqref{eq:4.14}.
Finally, substituting $u_\mu(s)$ into the objective of \eqref{eq:4.13} yields $\Phi_\mu(s)=\mu\ln\bigl(\sum_j e^{s^{(j)}/\mu}\bigr).
\end{proof}

content:
\begin{proposition}\label{prop:4.9}
In the matrix-game setting \eqref{eq:4.10}, under the entropy-distance setup of Lemma~3 the smoothed objective \eqref{eq:4.1} for the primal problem can be written explicitly as
\begin{equation}\label{eq:matrixgame_smooth}
\bar f_\mu(x)=\langle c,x\rangle_1+\mu\ln\Bigl(\frac1m\sum_{j=1}^m \exp\Bigl(\frac{\langle a_j,x\rangle_1+b^{(j)}}{\mu}\Bigr)\Bigr),
\qquad \min_{x\in\Delta_n}\ \bar f_\mu(x).
\end{equation}
\end{proposition}
(depend on: "Lemma 1.4.1.1", "Lemma 1.4.1.2", "Definition 1.4.1", "Definition 1.4.1.2")

proof:
\begin{proof}\label{proof:prop:4.9}
By definition of the entropy prox-function $d_2(u)=\ln m+\sum_j u^{(j)}\ln u^{(j)}$, the smoothed objective for \eqref{eq:4.10} is
\begin{equation}\label{eq:auto_Proposition_4_9_proof_1}
\bar f_\mu(x)=\langle c,x\rangle_1+\max_{u\in\Delta_m}\Bigl\{\sum_{j=1}^m u^{(j)}\bigl(\langle a_j,x\rangle_1+b^{(j)}\bigr)-\mu\sum_{j=1}^m u^{(j)}\ln u^{(j)}-\mu\ln m\Bigr\}.
\end{equation}
Let $s^{(j)}:=\langle a_j,x\rangle_1+b^{(j)}$. Lemma~4 gives
\begin{equation}\label{eq:auto_Proposition_4_9_proof_2}
\max_{u\in\Delta_m}\Bigl\{\sum_{j=1}^m u^{(j)}s^{(j)}-\mu\sum_{j=1}^m u^{(j)}\ln u^{(j)}\Bigr\}
=\mu\ln\Bigl(\sum_{j=1}^m e^{s^{(j)}/\mu}\Bigr).
\end{equation}
Therefore,
\begin{equation}\label{eq:auto_Proposition_4_9_proof_3}
\bar f_\mu(x)=\langle c,x\rangle_1+\mu\ln\Bigl(\sum_{j=1}^m e^{(\langle a_j,x\rangle_1+b^{(j)})/\mu}\Bigr)-\mu\ln m
=\langle c,x\rangle_1+\mu\ln\Bigl(\frac1m\sum_{j=1}^m e^{(\langle a_j,x\rangle_1+b^{(j)})/\mu}\Bigr),
\end{equation}
which is \eqref{eq:matrixgame_smooth}.
\end{proof}

