\begin{definition}\label{def:4.10}
Let $p\ge 1$ and let $m_j>0$ be weights. Given locations $c_j\in\mathbb{R}^n$ for $j=1,\dots,p$ and a radius $\bar r>0$, consider the continuous location problem
\begin{equation}\label{eq:4.15}
f^\ast := \min_{x}\Bigl\{ f(x):=\sum_{j=1}^p m_j\|x-c_j\|_1 \ :\ \|x\|_1\le \bar r \Bigr\}.
\tag{4.15}
\end{equation}
\end{definition}

\begin{proposition}\label{prop:4.11}
In the setting of Definition 4.10, choose $\|\cdot\|_1$ to be the Euclidean norm on $\mathbb{R}^n$ and take
\begin{equation}\label{eq:auto_Proposition_4_11_content_1}
d_1(x)=\frac12\|x\|_1^2 \quad\text{on}\quad Q_1:=\{x:\|x\|_1\le \bar r\}.
\end{equation}
Then $\sigma_1=1$ and
\begin{equation}\label{eq:auto_Proposition_4_11_content_2}
D_1=\max_{x\in Q_1} d_1(x)=\frac12\bar r^2.
\end{equation}
Let $E_2=(E_1^\ast)^p$ and
\begin{equation}\label{eq:auto_Proposition_4_11_content_3}
Q_2=\{u=(u_1,\dots,u_p)\in E_2:\ \|u_j\|_{1,*}\le 1,\ j=1,\dots,p\}.
\end{equation}
Choose
\begin{equation}\label{eq:auto_Proposition_4_11_content_4}
\|u\|_2:=\Bigl(\sum_{j=1}^p m_j\|u_j\|_{1,*}^2\Bigr)^{1/2},
\qquad
d_2(u):=\frac12\|u\|_2^2.
\end{equation}
Then $\sigma_2=1$ and, with $P:=\sum_{j=1}^p m_j$,
\begin{equation}\label{eq:auto_Proposition_4_11_content_5}
D_2=\max_{u\in Q_2} d_2(u)=\frac12P,
\qquad
\|A\|_{1,2}=P^{1/2}.
\end{equation}
Since $\hat f\equiv 0$ in \eqref{eq:4.1}, we have $M=0$, and the estimate \eqref{eq:4.3} yields the rate
\begin{equation}\label{eq:4.16}
f(\hat x)-f^\ast\le \frac{2P\bar r}{N+1}.
\tag{4.16}
\end{equation}
In particular, for the average objective $\tilde f(x):=\frac{1}{P}f(x)$ we have $\tilde f(\hat x)-\tilde f^\ast\le \frac{2\bar r}{N+1}$.
\end{proposition}
(depend on: "Definition 1.4.2.1", "Theorem 1.4.1", "Definition 1.4.1")

proof:
\begin{proof}\label{proof:prop:4.11}
With $d_1(x)=\frac12\|x\|_1^2$ and Euclidean norm, $d_1$ is $1$-strongly convex, hence $\sigma_1=1$, and the maximum of $d_1$ over the ball $\|x\|_1\le \bar r$ is $\frac12\bar r^2$, giving $D_1=\frac12\bar r^2$.

For $d_2(u)=\frac12\|u\|_2^2$ with $\|u\|_2^2=\sum_j m_j\|u_j\|_{1,*}^2$, the function $d_2$ is quadratic and therefore $1$-strongly convex with respect to $\|\cdot\|_2$, so $\sigma_2=1$. Over $Q_2$ we have $\|u_j\|_{1,*}\le 1$, hence $\|u\|_2^2\le \sum_j m_j=P$, so $D_2=\frac12P$.

The operator in the max-representation of $f(x)$ is $A x=(m_1 x,\dots,m_p x)$ acting into $E_2$. Thus
\begin{equation}\label{eq:auto_Proposition_4_11_proof_1}
\|A\|_{1,2}
=\max_{\|x\|_1=1}\|Ax\|_{2,*}
=\max_{\|x\|_1=1}\Bigl(\sum_{j=1}^p m_j\|x\|_1^2\Bigr)^{1/2}
=\sqrt{\sum_{j=1}^p m_j}=P^{1/2}.
\end{equation}
Finally, substituting $M=0$, $\sigma_1=\sigma_2=1$, $D_1=\frac12\bar r^2$, $D_2=\frac12P$, and $\|A\|_{1,2}=P^{1/2}$ into \eqref{eq:4.3} gives
\begin{equation}\label{eq:auto_Proposition_4_11_proof_2}
f(\hat x)-f^\ast\le \frac{4P^{1/2}}{N+1}\sqrt{\frac{(\bar r^2/2)(P/2)}{1\cdot 1}}
=\frac{2P\bar r}{N+1},
\end{equation}
which is \eqref{eq:4.16}. Dividing by $P$ yields the bound for $\tilde f$.
\end{proof}

content:
\begin{proposition}\label{prop:4.12}
In the setting of Proposition~4.11, the smoothed function $f_\mu$ admits the explicit representation
\begin{equation}\label{eq:auto_Proposition_4_12_content_1}
f_\mu(x)=\sum_{j=1}^p m_j\,\psi_\mu(\|x-c_j\|_1),
\end{equation}
where $\psi_\mu:[0,\infty)\to\mathbb{R}$ is given by
\begin{equation}\label{eq:4.17}
\psi_\mu(\tau):=\max_{\gamma\in[0,1]}\Bigl\{\gamma\tau-\frac12\mu\gamma^2\Bigr\}
=
\begin{cases}
\frac{\tau^2}{2\mu}, & 0\le \tau\le \mu,\\[4pt]
\tau-\frac{\mu}{2}, & \mu\le \tau.
\end{cases}
\tag{4.17}
\end{equation}
\end{proposition}
(depend on: "Proposition 1.4.2.1", "Definition 1.2.5")

proof:
\begin{proof}\label{proof:prop:4.12}
For fixed $x$, the maximization defining $f_\mu(x)$ separates across $j=1,\dots,p$ because $d_2(u)=\frac12\sum_j m_j\|u_j\|_{1,*}^2$ and $\langle Ax,u\rangle_2-\hat\phi(u)$ becomes $\sum_j m_j\langle u_j,x-c_j\rangle_1$.
Thus,
\begin{equation}\label{eq:auto_Proposition_4_12_proof_1}
f_\mu(x)=\sum_{j=1}^p m_j \max_{\|u_j\|_{1,*}\le 1}\Bigl\{\langle u_j,x-c_j\rangle_1-\frac{\mu}{2}\|u_j\|_{1,*}^2\Bigr\}.
\end{equation}
For each $j$, let $\tau_j:=\|x-c_j\|_1$. Writing $u_j=\gamma v_j$ with $\gamma\in[0,1]$ and $\|v_j\|_{1,*}=1$, we have $\max_{\|v_j\|_{1,*}=1}\langle v_j,x-c_j\rangle_1=\tau_j$ by definition of the dual norm.
Therefore,
\begin{equation}\label{eq:auto_Proposition_4_12_proof_2}
\max_{\|u_j\|_{1,*}\le 1}\Bigl\{\langle u_j,x-c_j\rangle_1-\frac{\mu}{2}\|u_j\|_{1,*}^2\Bigr\}
=\max_{\gamma\in[0,1]}\Bigl\{\gamma\tau_j-\frac{\mu}{2}\gamma^2\Bigr\}
=\psi_\mu(\tau_j).
\end{equation}
The closed-form expression \eqref{eq:4.17} follows by maximizing a concave quadratic over $\gamma\in[0,1]$: the unconstrained maximizer is $\gamma^\ast=\tau/\mu$, which lies in $[0,1]$ precisely when $\tau\le \mu$.
\end{proof}

