\begin{definition}\label{def:4.13}
Let $E$ be a finite-dimensional normed space with norm $\|\cdot\|_1$ and dual norm $\|\cdot\|_{1,*}$ on $E^\ast$.
Let $Q\subseteq E$ be a bounded closed convex set.
Let $B:E\to E^\ast$ be an affine operator of the form
\begin{equation}\label{eq:auto_Definition_4_13_content_1}
B(w)=\mathcal{B}w+b,
\end{equation}
where $\mathcal{B}:E\to E^\ast$ is linear and $b\in E^\ast$.
Assume that $\mathcal{B}$ is monotone:
\begin{equation}\label{eq:auto_Definition_4_13_content_2}
\langle \mathcal{B}h,h\rangle_1\ge 0\qquad \forall h\in E.
\end{equation}
The associated variational inequality problem is
\begin{equation}\label{eq:4.18}
\text{find } w^\ast\in Q \text{ such that }\ \langle B(w^\ast),w-w^\ast\rangle_1\ge 0\quad \forall w\in Q.
\tag{4.18}
\end{equation}
\end{definition}

\begin{definition}\label{def:4.14}
Define the gap function
\begin{equation}\label{eq:auto_Definition_4_14_content_1}
\psi(w):=\max_{v\in Q}\langle B(v),w-v\rangle_1.
\end{equation}
Consider the convex optimization problem
\begin{equation}\label{eq:4.19}
\min_{w\in Q}\ \psi(w).
\tag{4.19}
\end{equation}
\end{definition}
(depend on: "Definition 1.4.3.1")

\begin{lemma}\label{lem:5}
A point $w^\ast$ is a solution of the optimization problem \eqref{eq:4.19} if and only if it solves the variational inequality \eqref{eq:4.18}.
Moreover, for every solution $w^\ast$ of \eqref{eq:4.18} we have $\psi(w^\ast)=0$.
\end{lemma}
(depend on: "Definition 1.4.3.1", "Definition 1.4.3.2")

proof:
\begin{proof}\label{proof:lem:5}
First, note that $\psi(w)\ge 0$ for all $w\in Q$ because the maximization defining $\psi(w)$ includes $v=w$, which yields value $0$.

Assume $w^\ast$ solves \eqref{eq:4.18}. For any $v\in Q$, the monotonicity of $\mathcal{B}$ implies
\begin{equation}\label{eq:auto_Lemma_5_proof_1}
\langle B(v)-B(w^\ast),v-w^\ast\rangle_1=\langle \mathcal{B}(v-w^\ast),v-w^\ast\rangle_1\ge 0,
\end{equation}
hence $\langle B(v),v-w^\ast\rangle_1\ge \langle B(w^\ast),v-w^\ast\rangle_1$.
By \eqref{eq:4.18}, $\langle B(w^\ast),v-w^\ast\rangle_1\ge 0$, so $\langle B(v),v-w^\ast\rangle_1\ge 0$, equivalently $\langle B(v),w^\ast-v\rangle_1\le 0$.
Taking the maximum over $v\in Q$ gives $\psi(w^\ast)\le 0$. Since $\psi(w^\ast)\ge 0$, we conclude $\psi(w^\ast)=0$, so $w^\ast$ minimizes $\psi$ in \eqref{eq:4.19}.

Conversely, suppose $w^\ast$ minimizes \eqref{eq:4.19}. Then $\psi(w^\ast)=\min_{w\in Q}\psi(w)\ge 0$ and, by choosing $v=w^\ast$ in the definition of $\psi(w^\ast)$, we also have $\psi(w^\ast)\ge 0$, hence $\psi(w^\ast)=0$.
In particular, for all $v\in Q$,
\begin{equation}\label{eq:auto_Lemma_5_proof_2}
\langle B(v),w^\ast-v\rangle_1\le 0
\qquad\Longleftrightarrow\qquad
\langle B(v),v-w^\ast\rangle_1\ge 0.
\end{equation}
If $w^\ast$ did not satisfy \eqref{eq:4.18}, there would exist $v_1\in Q$ such that $\langle B(w^\ast),v_1-w^\ast\rangle_1<0$.
For $\alpha\in[0,1]$, define $v_\alpha:=w^\ast+\alpha(v_1-w^\ast)\in Q$ by convexity of $Q$.
Then
\begin{equation}\label{eq:auto_Lemma_5_proof_3}
0\le \langle B(v_\alpha),v_\alpha-w^\ast\rangle_1
=\alpha\langle B(w^\ast),v_1-w^\ast\rangle_1+\alpha^2\langle \mathcal{B}(v_1-w^\ast),v_1-w^\ast\rangle_1.
\end{equation}
The second term is nonnegative by monotonicity of $\mathcal{B}$, while the first term is strictly negative for $\alpha>0$.
For $\alpha$ sufficiently small, the right-hand side becomes negative, contradicting the inequality. Therefore $w^\ast$ must satisfy \eqref{eq:4.18}.
\end{proof}

