\begin{proposition}\label{prop:4.15}
A primal max-structure representation of the objective $\psi$ in \eqref{eq:4.19} can be obtained by taking
\begin{equation}\label{eq:auto_Proposition_4_15_content_1}
E_1=E_2=E,\quad Q_1=Q_2=Q,\quad d_1=d_2=d,\quad A=\mathcal{B},
\end{equation}
\begin{equation}\label{eq:auto_Proposition_4_15_content_2}
\hat f(x)=\langle b,x\rangle_1,
\qquad
\hat\phi(u)=\langle b,u\rangle_1+\langle \mathcal{B}u,u\rangle_1.
\end{equation}
Then the smoothed oracle computation for $f_\mu(x)$ reduces to solving
\begin{equation}\label{eq:4.20}
\max_{u\in Q}\ \bigl\{\langle \mathcal{B}x,u\rangle_1-\mu d(u)-\langle b,u\rangle_1+\langle \mathcal{B}u,u\rangle_1\bigr\}.
\tag{4.20}
\end{equation}
\end{proposition}
(depend on: "Definition 1.4.3.2", "Definition 1.2.2", "Definition 1.2.5")

proof:
\begin{proof}\label{proof:prop:4.15}
By definition,
\begin{equation}\label{eq:auto_Proposition_4_15_proof_1}
\psi(w)=\max_{v\in Q}\langle B(v),w-v\rangle_1
=\max_{v\in Q}\bigl[\langle \mathcal{B}v+b,w\rangle_1-\langle \mathcal{B}v+b,v\rangle_1\bigr]
=\langle b,w\rangle_1+\max_{v\in Q}\bigl[\langle \mathcal{B}w,v\rangle_1-\langle b,v\rangle_1+\langle \mathcal{B}v,v\rangle_1\bigr].
\end{equation}
This is of the form \eqref{eq:2.2} with $\hat f(w)=\langle b,w\rangle_1$, $A=\mathcal{B}$ and $\hat\phi(v)=\langle b,v\rangle_1+\langle \mathcal{B}v,v\rangle_1$.
Applying the smoothing definition \eqref{eq:2.5} to this max-term yields exactly the maximization problem \eqref{eq:4.20}.
\end{proof}

