\begin{proposition}\label{prop:4.16}
Assume that $\hat f(x)=\langle b,x\rangle_1$ in Proposition~4.15 so that $M=0$. Then Theorem~3 yields the following estimate for the iteration complexity of solving the variational inequality \eqref{eq:4.18} to accuracy $\varepsilon>0$:
\begin{equation}\label{eq:4.21}
N\ \le\ \frac{4D_1\|\mathcal{B}\|_{1,2}}{\sigma_1\,\varepsilon}.
\tag{4.21}
\end{equation}
\end{proposition}
(depend on: "Proposition 1.4.3.1", "Theorem 1.4.1", "Definition 1.4.2", "Definition 1.4.3.1")

proof:
\begin{proof}\label{proof:prop:4.16}
In this setting, the smooth part $\hat f$ is linear, hence $M=0$.
Applying \eqref{eq:4.4} with $A=\mathcal{B}$, $M=0$, and $D_2=D_1$, $\sigma_2=\sigma_1$ (because $Q_1=Q_2=Q$ and $d_1=d_2=d$) gives
\begin{equation}\label{eq:auto_Proposition_4_16_proof_1}
N\le \frac{4\|\mathcal{B}\|_{1,2}}{\varepsilon}\sqrt{\frac{D_1D_2}{\sigma_1\sigma_2}}
=\frac{4\|\mathcal{B}\|_{1,2}}{\varepsilon}\cdot\frac{D_1}{\sigma_1},
\end{equation}
which is \eqref{eq:4.21}.
\end{proof}

