\begin{proposition}\label{prop:4.17}
A dual max-structure representation of \eqref{eq:4.19} is obtained from the identity
\begin{equation}\label{eq:auto_Proposition_4_17_content_1}
\min_{w\in Q}\max_{v\in Q}\langle B(v),w-v\rangle_1
=\max_{v\in Q}\min_{w\in Q}\langle B(v),w-v\rangle_1
=-\min_{v\in Q}\max_{w\in Q}\langle B(v),v-w\rangle_1.
\end{equation}
Equivalently, we may take $E_1=E_2=E$, $Q_1=Q_2=Q$, $d_1=d_2=d$, $A=\mathcal{B}$ and
\begin{equation}\label{eq:auto_Proposition_4_17_content_2}
\hat f(x)=\langle b,x\rangle_1+\langle \mathcal{B}x,x\rangle_1,
\qquad
\hat\phi(u)=\langle b,u\rangle_1.
\end{equation}
Then the oracle computation becomes
\begin{equation}\label{eq:auto_Proposition_4_17_content_3}
f_\mu(x)=\max_{u\in Q}\bigl\{\langle \mathcal{B}x,u\rangle_1-\mu d(u)-\langle b,u\rangle_1\bigr\}.
\end{equation}
In this dual representation the smoothness constant becomes $M=\|\mathcal{B}\|_{1,2}$, and the complexity bound corresponding to \eqref{eq:4.21} increases to
\begin{equation}\label{eq:auto_Proposition_4_17_content_4}
N\ \le\ \frac{4D_1\|\mathcal{B}\|_{1,2}}{\sigma_1\,\varepsilon}
+\sqrt{\frac{D_1\|\mathcal{B}\|_{1,2}}{\sigma_1\,\varepsilon}}.
\end{equation}
\end{proposition}
(depend on: "Definition 1.4.3.2", "Theorem 1.4.1", "Definition 1.2.5", "Proposition 1.4.3.2")

\begin{definition}\label{def:4.18}
Let $a_j\in E_1^\ast$ and $b^{(j)}\in\mathbb{R}$ for $j=1,\dots,m$. Consider the piecewise linear minimization problem
\begin{equation}\label{eq:4.22}
\min_{x\in Q_1}\ f(x),
\qquad
f(x):=\max_{1\le j\le m}\bigl|\langle a_j,x\rangle_1-b^{(j)}\bigr|.
\tag{4.22}
\end{equation}
\end{definition}

\begin{proposition}\label{prop:4.19}
In the setting of Definition 4.18, choose the Euclidean norm on $E_1=\mathbb{R}^n$ and the quadratic prox-function
\begin{equation}\label{eq:auto_Proposition_4_19_content_1}
\|x\|_1:=\Bigl(\sum_{i=1}^n (x^{(i)})^2\Bigr)^{1/2},
\qquad
d_1(x):=\frac12\|x\|_1^2,
\qquad
\bar r:=\max_{x\in Q_1}\|x\|_1.
\end{equation}
Introduce $E_2=\mathbb{R}^{2m}$, $\Delta_{2m}\subset\mathbb{R}^{2m}$, and define
\begin{equation}\label{eq:auto_Proposition_4_19_content_2}
\hat A:=\begin{pmatrix}A\\-A\end{pmatrix},
\qquad
\hat b:=\begin{pmatrix}b\\-b\end{pmatrix},
\end{equation}
where $A$ is the matrix with rows $a_j$ and $b\in\mathbb{R}^m$ collects the scalars $b^{(j)}$.
Then
\begin{equation}\label{eq:auto_Proposition_4_19_content_3}
f(x)=\max_{u\in\Delta_{2m}}\bigl\{\langle \hat A x,u\rangle_2-\langle \hat b,u\rangle_2\bigr\}.
\end{equation}
With the entropy prox-function on $\Delta_{2m}$,
\begin{equation}\label{eq:auto_Proposition_4_19_content_4}
d_2(u):=\ln(2m)+\sum_{j=1}^{2m} u^{(j)}\ln u^{(j)},
\end{equation}
we have $\sigma_1=\sigma_2=1$, $D_1=\frac12\bar r^2$, $D_2=\ln(2m)$ and
\begin{equation}\label{eq:auto_Proposition_4_19_content_5}
\|\hat A\|_{1,2}=\max_{1\le j\le m}\|a_j\|_{1,*}.
\end{equation}
Therefore, the complexity estimate \eqref{eq:4.4} yields that \eqref{eq:4.22} can be solved to accuracy $\varepsilon$ in at most
\begin{equation}\label{eq:auto_Proposition_4_19_content_6}
N \le 2\sqrt{2}\,\bar r\Bigl(\max_{1\le j\le m}\|a_j\|_{1,*}\Bigr)\sqrt{\ln(2m)}\cdot\frac{1}{\varepsilon}
\end{equation}
iterations of Algorithm~3.11.
Moreover, the smooth approximation of the objective in \eqref{eq:4.22} takes the explicit form
\begin{equation}\label{eq:4.22_smooth}
\bar f_\mu(x)=\mu\ln\Bigl(\frac1m\sum_{j=1}^m \xi\Bigl(\frac{1}{\mu}\bigl[\langle a_j,x\rangle_1+b^{(j)}\bigr]\Bigr)\Bigr),
\qquad
\xi(\tau):=\frac12\bigl(e^\tau+e^{-\tau}\bigr).
\end{equation}
\end{proposition}
(depend on: "Definition 1.4.4.1", "Lemma 1.4.1.1", "Lemma 1.4.1.2", "Theorem 1.4.1", "Algorithm 3.11")

proof:
\begin{proof}\label{proof:prop:4.19}
The identity
\begin{equation}\label{eq:auto_Proposition_4_19_proof_1}
\max_{1\le j\le m}|\langle a_j,x\rangle_1-b^{(j)}|
=\max\Bigl\{\max_{1\le j\le m}(\langle a_j,x\rangle_1-b^{(j)}),\ \max_{1\le j\le m}(-\langle a_j,x\rangle_1+b^{(j)})\Bigr\}
\end{equation}
can be written as a single maximum over $2m$ affine functions, which yields
\begin{equation}\label{eq:auto_Proposition_4_19_proof_2}
f(x)=\max_{u\in\Delta_{2m}}\{\langle \hat A x,u\rangle_2-\langle \hat b,u\rangle_2\}.
\end{equation}
With Euclidean norm and quadratic prox $d_1$, we have $\sigma_1=1$ and $D_1=\frac12\bar r^2$.
With the entropy prox on $\Delta_{2m}$, Lemma~3 implies $\sigma_2=1$ and $D_2=\ln(2m)$.

To compute $\|\hat A\|_{1,2}$, note that for $\|x\|_1=1$,
\begin{equation}\label{eq:auto_Proposition_4_19_proof_3}
\|\hat A x\|_\infty=\max\Bigl\{\max_{1\le j\le m}|\langle a_j,x\rangle_1|,\ \max_{1\le j\le m}|\langle -a_j,x\rangle_1|\Bigr\}
=\max_{1\le j\le m}|\langle a_j,x\rangle_1|.
\end{equation}
Maximizing over $\|x\|_1=1$ gives $\|\hat A\|_{1,2}=\max_{1\le j\le m}\|a_j\|_{1,*}$.

Since the smooth part is absent here ($M=0$), applying \eqref{eq:4.4} yields
\begin{equation}\label{eq:auto_Proposition_4_19_proof_4}
N\le \frac{4\|\hat A\|_{1,2}}{\varepsilon}\sqrt{\frac{D_1D_2}{\sigma_1\sigma_2}}
=\frac{4}{\varepsilon}\Bigl(\max_{1\le j\le m}\|a_j\|_{1,*}\Bigr)\sqrt{\frac{(\bar r^2/2)\ln(2m)}{1}}
=2\sqrt{2}\,\bar r\Bigl(\max_{1\le j\le m}\|a_j\|_{1,*}\Bigr)\sqrt{\ln(2m)}\cdot\frac{1}{\varepsilon}.
\end{equation}

Finally, the formula \eqref{eq:4.22_smooth} follows by applying Lemma~4 to the $2m$ affine pieces with the entropy prox-function, and rewriting the resulting log-sum-exp in terms of $\xi(\tau)=\frac12(e^\tau+e^{-\tau})$.
\end{proof}

