\begin{definition}\label{def:4.20}
Let $a_j\in E_1^\ast$ and $b^{(j)}\in\mathbb{R}$ for $j=1,\dots,m$. Consider the problem of minimizing the sum of absolute values
\begin{equation}\label{eq:4.23}
\min_{x\in Q_1}\ f(x),
\qquad
f(x):=\sum_{j=1}^m\bigl|\langle a_j,x\rangle_1-b^{(j)}\bigr|.
\tag{4.23}
\end{equation}
\end{definition}

\begin{proposition}\label{prop:4.21}
In the setting of Definition 4.20, let $A$ be the matrix with rows $a_j$ and choose
\begin{equation}\label{eq:auto_Proposition_4_21_content_1}
E_2=\mathbb{R}^m,
\qquad
Q_2=\{u\in\mathbb{R}^m:\ |u^{(j)}|\le 1,\ j=1,\dots,m\},
\end{equation}
\begin{equation}\label{eq:auto_Proposition_4_21_content_2}
d_2(u)=\frac12\|u\|_2^2
=\frac12\sum_{j=1}^m \|a_j\|_{1,*}\,\bigl(u^{(j)}\bigr)^2.
\end{equation}
Then the smooth approximation of $f$ can be written as
\begin{equation}\label{eq:auto_Proposition_4_21_content_3}
f_\mu(x)=\max_{u\in Q_2}\{\langle Ax-b,u\rangle_2-\mu d_2(u)\}
=\sum_{j=1}^m \|a_j\|_{1,*}\,\psi_\mu\Bigl(\frac{|\langle a_j,x\rangle_1-b^{(j)}|}{\|a_j\|_{1,*}}\Bigr),
\end{equation}
where $\psi_\mu$ is the function in \eqref{eq:4.17}.
Moreover, with $D:=\sum_{j=1}^m \|a_j\|_{1,*}$ we have $D_2=\frac12 D$ and $\sigma_2=1$, and the operator norm satisfies
\begin{equation}\label{eq:auto_Proposition_4_21_content_4}
\|A\|_{1,2}\le D^{1/2}.
\end{equation}
Therefore, in the case $M=0$ the complexity bound of Theorem~3 yields
\begin{equation}\label{eq:auto_Proposition_4_21_content_5}
N\ \le\ \frac{2}{\varepsilon}\sqrt{\frac{2D_1}{\sigma_1}}\ \sum_{j=1}^m \|a_j\|_{1,*}.
\end{equation}
\end{proposition}
(depend on: "Definition 1.4.4.2", "Proposition 1.4.2.2", "Theorem 1.4.1", "Definition 1.2.5")

proof:
\begin{proof}\label{proof:prop:4.21}
For $x\in Q_1$,
\begin{equation}\label{eq:auto_Proposition_4_21_proof_1}
f(x)=\sum_{j=1}^m |\langle a_j,x\rangle_1-b^{(j)}|
=\max_{u\in Q_2}\ \langle Ax-b,u\rangle_2,
\end{equation}
because the maximizer chooses $u^{(j)}=\operatorname{sign}(\langle a_j,x\rangle_1-b^{(j)})$ with $|u^{(j)}|\le 1$.
Applying the smoothing definition \eqref{eq:2.5} with the quadratic prox-function $d_2$ gives
\begin{equation}\label{eq:auto_Proposition_4_21_proof_2}
f_\mu(x)=\max_{u\in Q_2}\{\langle Ax-b,u\rangle_2-\mu d_2(u)\}.
\end{equation}
This maximization separates over coordinates $u^{(j)}$ and, after scaling by $\|a_j\|_{1,*}$, reduces to the one-dimensional maximization defining $\psi_\mu$ in \eqref{eq:4.17}, which yields the stated sum representation.

Since $|u^{(j)}|\le 1$ on $Q_2$, we have
\begin{equation}\label{eq:auto_Proposition_4_21_proof_3}
d_2(u)=\frac12\sum_{j=1}^m \|a_j\|_{1,*}(u^{(j)})^2\le \frac12\sum_{j=1}^m \|a_j\|_{1,*}=\frac12D,
\end{equation}
hence $D_2=\frac12D$. The function $d_2$ is quadratic, so $\sigma_2=1$.

To bound the operator norm, note that by Cauchy--Schwarz,
\begin{equation}\label{eq:auto_Proposition_4_21_proof_4}
\langle Ax,u\rangle_2=\sum_{j=1}^m u^{(j)}\langle a_j,x\rangle_1
\le \sum_{j=1}^m \|a_j\|_{1,*}|u^{(j)}|\,\|x\|_1.
\end{equation}
If $\|x\|_1=1$ and $\|u\|_2=1$, then $\sum_j \|a_j\|_{1,*}(u^{(j)})^2\le 1$ and hence
\begin{equation}\label{eq:auto_Proposition_4_21_proof_5}
\sum_{j=1}^m \|a_j\|_{1,*}|u^{(j)}|
\le \Bigl(\sum_{j=1}^m \|a_j\|_{1,*}\Bigr)^{1/2}\Bigl(\sum_{j=1}^m \|a_j\|_{1,*}(u^{(j)})^2\Bigr)^{1/2}
\le D^{1/2}.
\end{equation}
Therefore $\|A\|_{1,2}\le D^{1/2}$.

Finally, when $M=0$, Theorem~3 gives $N+1\le \frac{4\|A\|_{1,2}}{\varepsilon}\sqrt{\frac{D_1D_2}{\sigma_1\sigma_2}}$.
Substituting $\|A\|_{1,2}\le D^{1/2}$, $D_2=\frac12D$, and $\sigma_2=1$ yields
\begin{equation}\label{eq:auto_Proposition_4_21_proof_6}
N+1\le \frac{4D^{1/2}}{\varepsilon}\sqrt{\frac{D_1(D/2)}{\sigma_1}}
=\frac{2D}{\varepsilon}\sqrt{\frac{2D_1}{\sigma_1}}
=\frac{2}{\varepsilon}\sqrt{\frac{2D_1}{\sigma_1}}\sum_{j=1}^m \|a_j\|_{1,*}.
\end{equation}
\end{proof}

