\begin{lemma}\label{lem:6}
For any $g\in E^\ast$ and $h\in E$ and any $L>0$, we have
\begin{equation}\label{eq:lem6}
\langle g,h\rangle_1+\frac12L\|h\|_1^2
=
\max_{s\in E^\ast}\Bigl\{\langle s,h\rangle_1-\frac{1}{2L}\|s-g\|_{1,*}^2\Bigr\}.
\end{equation}
\end{lemma}

proof:
\begin{proof}\label{proof:lem:6}
For any $h\in E$,
\begin{equation}\label{eq:auto_Lemma_6_proof_1}
\frac12L\|h\|_1^2=\max_{r\ge 0}\Bigl\{r\|h\|_1-\frac{1}{2L}r^2\Bigr\},
\end{equation}
because the right-hand side is a concave quadratic in $r$ with maximizer $r=L\|h\|_1$.
Using the definition of the dual norm, $\|h\|_1=\max_{\|s\|_{1,*}=1}\langle s,h\rangle_1$, we obtain
\begin{equation}\label{eq:auto_Lemma_6_proof_2}
\langle g,h\rangle_1+\frac12L\|h\|_1^2
=\max_{r\ge 0}\max_{\|s\|_{1,*}=1}\Bigl\{\langle g,h\rangle_1+r\langle s,h\rangle_1-\frac{1}{2L}r^2\Bigr\}.
\end{equation}
Letting $t=rs$ ranges over all $t\in E^\ast$ and yields
\begin{equation}\label{eq:auto_Lemma_6_proof_3}
\langle g,h\rangle_1+\frac12L\|h\|_1^2
=\max_{t\in E^\ast}\Bigl\{\langle g+t,h\rangle_1-\frac{1}{2L}\|t\|_{1,*}^2\Bigr\}.
\end{equation}
Finally, substitute $s=g+t$ (equivalently, $t=s-g$) to get
\begin{equation}\label{eq:auto_Lemma_6_proof_4}
\langle g,h\rangle_1+\frac12L\|h\|_1^2
=\max_{s\in E^\ast}\Bigl\{\langle s,h\rangle_1-\frac{1}{2L}\|s-g\|_{1,*}^2\Bigr\},
\end{equation}
which is \eqref{eq:lem6}.
\end{proof}

