\begin{definition}\label{def:5.1}
Let $\bar x\in\Delta_n$ and $\bar g\in\mathbb{R}^n$. Consider the problem that appears in the computation of the proximal mapping $T_Q$ for the simplex with the $\ell_1$ norm:
\begin{equation}\label{eq:5.1}
\psi^\ast
:=
\min_{x\in\Delta_n}\Bigl\{\langle \bar g,x-\bar x\rangle_1+\frac12L\|x-\bar x\|_1^2\Bigr\}.
\tag{5.1}
\end{equation}
\end{definition}
(depend on: "Definition 1.4.1.1")

\begin{proposition}\label{prop:5.2}
In the setting of Definition 5.1, without loss of generality we may assume that
\begin{equation}\label{eq:5.2}
\min_{1\le i\le n}\ \bar g^{(i)}=0.
\tag{5.2}
\end{equation}
\end{proposition}
(depend on: "Definition 1.5.1")

proof:
\begin{proof}\label{proof:prop:5.2}
Let $\alpha:=\min_i \bar g^{(i)}$ and define $\bar g':=\bar g-\alpha \mathbf{1}$, where $\mathbf{1}=(1,\dots,1)\in\mathbb{R}^n$.
For any $x\in\Delta_n$, we have $\langle \mathbf{1},x-\bar x\rangle_1=\sum_i (x^{(i)}-\bar x^{(i)})=0$ because both $x$ and $\bar x$ lie in the simplex.
Therefore $\langle \bar g',x-\bar x\rangle_1=\langle \bar g,x-\bar x\rangle_1$ for all feasible $x$, so the objective in \eqref{eq:5.1} is unchanged by replacing $\bar g$ with $\bar g'$.
By construction, $\min_i \bar g'^{(i)}=0$, which proves \eqref{eq:5.2}.
\end{proof}

