\begin{proposition}\label{prop:5.3}
Assume the setup of Definition~5.1 and the normalization \eqref{eq:5.2}.
Let $\|\cdot\|$ denote the $\ell_\infty$ norm on $\mathbb{R}^n$, so that $\|s\|=\max_i |s^{(i)}|$.
Then the optimal value $\psi^\ast$ of \eqref{eq:5.1} satisfies the dual representation
\begin{equation}\label{eq:5.3}
-\psi^\ast
=
\min_{\tau\ge 0}
\Bigl\{
\sum_{i=1}^n \bar x^{(i)}\,(\bar g^{(i)}-2\tau)_+
+\frac{\tau^2}{2L}
\Bigr\},
\qquad (a)_+:=\max\{a,0\}.
\end{equation}
Consequently, $\psi^\ast$ can be computed by a one-dimensional search over $\tau\ge 0$ after sorting the components of $\bar g$.
\end{proposition}
(depend on: "Lemma 1.5.1", "Definition 1.5.1", "Proposition 1.5.1")

proof:
\begin{proof}\label{proof:prop:5.3}
By Lemma~6 applied with $h=x-\bar x$ and $g=\bar g$, we can rewrite \eqref{eq:5.1} as
\begin{equation}\label{eq:auto_Proposition_5_3_proof_1}
\psi^\ast=\min_{x\in\Delta_n}\max_{s\in\mathbb{R}^n}\Bigl\{\langle \bar g+s,x-\bar x\rangle_1-\frac{1}{2L}\|s\|_\infty^2\Bigr\}.
\end{equation}
Exchanging $\min$ and $\max$ yields
\begin{equation}\label{eq:auto_Proposition_5_3_proof_2}
\psi^\ast=\max_{s\in\mathbb{R}^n}\Bigl\{-\langle \bar g+s,\bar x\rangle_1-\frac{1}{2L}\|s\|_\infty^2+\min_{x\in\Delta_n}\langle \bar g+s,x\rangle_1\Bigr\}.
\end{equation}
The inner minimization over the simplex equals $\min_i (\bar g^{(i)}+s^{(i)})$.
Using the normalization \eqref{eq:5.2}, we can enforce $\min_i (\bar g^{(i)}+s^{(i)})=0$ by shifting all components of $s$ by the same constant, and thus we arrive at the equivalent minimization form
\begin{equation}\label{eq:auto_Proposition_5_3_proof_3}
-\psi^\ast
=
\min_{s\in\mathbb{R}^n,\ \lambda\ge 0}
\Bigl\{\langle s,\bar x\rangle_1+\frac{1}{2L}\|s-\bar g\|_\infty^2-\lambda:\ s^{(i)}\ge \lambda,\ i=1,\dots,n\Bigr\}.
\end{equation}
Now introduce $\tau:=\|s-\bar g\|_\infty\ge 0$. The constraint $\|s-\bar g\|_\infty\le\tau$ is equivalent to the coordinate-wise inequalities $\bar g^{(i)}-\tau\le s^{(i)}\le \bar g^{(i)}+\tau$.
Together with $s^{(i)}\ge\lambda$, the optimal $s^{(i)}$ equals $\max\{\lambda,\bar g^{(i)}-\tau\}$.
The feasibility conditions imply $\lambda\le \tau$.
Substituting the optimal $s$ and minimizing in $\lambda$ gives $\lambda^\ast=\tau$, and hence
\begin{equation}\label{eq:auto_Proposition_5_3_proof_4}
-\psi^\ast
=
\min_{\tau\ge 0}\Bigl\{
\sum_{i=1}^n \bar x^{(i)}\max\{\tau,\bar g^{(i)}-\tau\}+\frac{\tau^2}{2L}-\tau
\Bigr\}
=
\min_{\tau\ge 0}\Bigl\{
\sum_{i=1}^n \bar x^{(i)}(\bar g^{(i)}-2\tau)_++\frac{\tau^2}{2L}
\Bigr\},
\end{equation}
which is \eqref{eq:5.3}.
The objective is piecewise differentiable with breakpoints at $\tau_i=\bar g^{(i)}/2$, so sorting the components of $\bar g$ enables a finite check of candidate intervals.
\end{proof}

