\begin{definition}\label{def:5.4}
For $\mu>0$ and $u\in\mathbb{R}^m$, define the log-sum-exp smoothing function
\begin{equation}\label{eq:5.4}
\eta(u):=\mu\ln\Bigl(\sum_{j=1}^m e^{u^{(j)}/\mu}\Bigr).
\tag{5.4}
\end{equation}
\end{definition}

\begin{proposition}\label{prop:5.5}
Let $\eta$ be defined by \eqref{eq:5.4}. For any $u\in\mathbb{R}^m$, let $\bar u:=\max_{1\le j\le m}u^{(j)}$ and define $v\in\mathbb{R}^m$ by $v^{(j)}:=u^{(j)}-\bar u$.
Then
\begin{equation}\label{eq:auto_Proposition_5_5_content_1}
\eta(u)=\bar u+\eta(v),
\qquad
\nabla \eta(u)=\nabla \eta(v).
\end{equation}
\end{proposition}
(depend on: "Definition 1.5.2.1")

proof:
\begin{proof}\label{proof:prop:5.5}
We have
\begin{equation}\label{eq:auto_Proposition_5_5_proof_1}
\sum_{j=1}^m e^{u^{(j)}/\mu}
=\sum_{j=1}^m e^{(v^{(j)}+\bar u)/\mu}
=e^{\bar u/\mu}\sum_{j=1}^m e^{v^{(j)}/\mu}.
\end{equation}
Taking logarithms and multiplying by $\mu$ yields
\begin{equation}\label{eq:auto_Proposition_5_5_proof_2}
\eta(u)=\mu\ln\Bigl(e^{\bar u/\mu}\sum_{j=1}^m e^{v^{(j)}/\mu}\Bigr)
=\bar u+\mu\ln\Bigl(\sum_{j=1}^m e^{v^{(j)}/\mu}\Bigr)
=\bar u+\eta(v).
\end{equation}
The gradient of $\eta$ is the softmax:
\begin{equation}\label{eq:auto_Proposition_5_5_proof_3}
\frac{\partial \eta}{\partial u^{(j)}}(u)
=\frac{e^{u^{(j)}/\mu}}{\sum_{\ell=1}^m e^{u^{(\ell)}/\mu}}
=\frac{e^{v^{(j)}/\mu}}{\sum_{\ell=1}^m e^{v^{(\ell)}/\mu}}
=\frac{\partial \eta}{\partial v^{(j)}}(v),
\end{equation}
hence $\nabla\eta(u)=\nabla\eta(v)$.
\end{proof}

