\begin{definition}\label{def:5.6}
Assume that the prox-function $d:Q\to\mathbb{R}$ is differentiable and $\sigma$-strongly convex on $Q$ with respect to $\|\cdot\|$.
Define the Bregman distance associated with $d$ by
\begin{equation}\label{eq:auto_Definition_5_6_content_1}
\xi(z,x):=d(x)-d(z)-\langle \nabla d(z),x-z\rangle,\qquad z,x\in Q.
\end{equation}
Then $\xi(z,x)\ge \frac{\sigma}{2}\|x-z\|^2$ for all $z,x\in Q$.
Define the mapping
\begin{equation}\label{eq:auto_Definition_5_6_content_2}
V_Q(z,g):=\arg\min_{x\in Q}\bigl\{\langle g,x-z\rangle+\xi(z,x)\bigr\}.
\end{equation}
\end{definition}
(depend on: "Definition 1.3.5")

\begin{lemma}\label{lem:7}
Let the sequence $\{\alpha_k\}_{k=0}^\infty$ satisfy condition \eqref{eq:3.6} and suppose that relation \eqref{eq:Rk} holds for some $k\ge 0$.
Choose
\begin{equation}\label{eq:auto_Lemma_7_content_1}
\gamma_k:=\frac{\sigma}{L}\alpha_{k+1}.
\end{equation}
Define
\begin{equation}\label{eq:5.5}
x_{k+1}=\tau_k z_k+(1-\tau_k)y_k,
\qquad
\hat x_{k+1}=V_Q\bigl(z_k,\gamma_k\nabla f(x_{k+1})\bigr),
\qquad
y_{k+1}=\tau_k\hat x_{k+1}+(1-\tau_k)y_k.
\tag{5.5}
\end{equation}
Then the relation $(R_{k+1})$ holds.
\end{lemma}
(depend on: "Definition 1.5.3.1", "Lemma 2", "Proposition 1.3.4", "Lemma 1.3.1", "Definition 1.3.4")

proof:
\begin{proof}\label{proof:lem:7}
Denote
\begin{equation}\label{eq:auto_Lemma_7_proof_1}
l_k(x)=\beta_k+\langle l_k,x-z_k\rangle
:=\sum_{i=0}^{k}\alpha_i\bigl[f(x_i)+\langle \nabla f(x_i),x-x_i\rangle\bigr].
\end{equation}
Since $z_k$ minimizes $\frac{L}{\sigma}d(x)+l_k(x)$ over $x\in Q$, the first-order optimality condition gives
\begin{equation}\label{eq:lem7_opt_zk}
\Bigl\langle \frac{L}{\sigma}\nabla d(z_k)+l_k,\ x-z_k\Bigr\rangle\ge 0\qquad \forall x\in Q.
\end{equation}
Let $\psi_k:=\frac{L}{\sigma}d(z_k)+\beta_k$. Using the identity
\begin{equation}\label{eq:auto_Lemma_7_proof_2}
d(x)=\xi(z_k,x)+d(z_k)+\langle \nabla d(z_k),x-z_k\rangle,
\end{equation}
we obtain for any $x\in Q$:
\begin{align}
\frac{L}{\sigma}d(x)+l_k(x)+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle
&=\frac{L}{\sigma}\xi(z_k,x)+\psi_k+\Bigl\langle \frac{L}{\sigma}\nabla d(z_k)+l_k,\ x-z_k\Bigr\rangle\nonumber\\
&\quad+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle\nonumber\\
&\ge \frac{L}{\sigma}\xi(z_k,x)+\psi_k+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle,\label{eq:lem7_main1}
\end{align}
where we used \eqref{eq:lem7_opt_zk}.

Since $(R_k)$ holds and $A_{k+1}=A_k+\alpha_{k+1}$, we have $\psi_k\ge A_{k+1}f(x_{k+1})$ and hence
\begin{equation}\label{eq:auto_Lemma_7_proof_3}
\frac{L}{\sigma}d(x)+l_k(x)+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-x_{k+1}\rangle
\ge \frac{L}{\sigma}\xi(z_k,x)+A_{k+1}f(x_{k+1})+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-z_k\rangle.
\end{equation}
Taking the minimum over $x\in Q$ yields
\begin{align}
\psi_{k+1}
&\ge \min_{x\in Q}\Bigl\{\frac{L}{\sigma}\xi(z_k,x)+A_{k+1}f(x_{k+1})+\alpha_{k+1}\langle \nabla f(x_{k+1}),x-z_k\rangle\Bigr\}\nonumber\\
&=\frac{L}{\sigma}\xi(z_k,\hat x_{k+1})+A_{k+1}f(x_{k+1})
+\alpha_{k+1}\langle \nabla f(x_{k+1}),\hat x_{k+1}-z_k\rangle,\label{eq:lem7_main2}
\end{align}
where $\hat x_{k+1}$ is defined by \eqref{eq:5.5} and the choice of $\gamma_k$.

By strong convexity of $d$, we have $\xi(z_k,\hat x_{k+1})\ge \frac{\sigma}{2}\|\hat x_{k+1}-z_k\|^2$. Using $\tau_k=\alpha_{k+1}/A_{k+1}$ and the definition of $y_{k+1}$, we obtain
\begin{equation}\label{eq:auto_Lemma_7_proof_4}
y_{k+1}-x_{k+1}=\tau_k(\hat x_{k+1}-z_k).
\end{equation}
Combining this identity with \eqref{eq:lem7_main2} shows that
\begin{equation}\label{eq:auto_Lemma_7_proof_5}
\psi_{k+1}\ge A_{k+1}\Bigl(f(x_{k+1})+\langle \nabla f(x_{k+1}),y_{k+1}-x_{k+1}\rangle\Bigr).
\end{equation}
By convexity of $f$, the right-hand side is at least $A_{k+1}f(y_{k+1})$, hence $(R_{k+1})$ holds.
\end{proof}

