\begin{algorithm}\label{alg:5.6}
Choose an initial point
\begin{equation}\label{eq:5.6_init}
y_0=z_0=\arg\min_{x\in Q}\Bigl\{\frac{L}{\sigma}d(x)+\frac12\bigl[f(x_0)+\langle \nabla f(x_0),x-x_0\rangle\bigr]\Bigr\}.
\end{equation}
For $k\ge 0$, iterate:
\begin{equation}\label{eq:5.6}
\begin{aligned}
\text{(a)}\quad &z_k=\arg\min_{x\in Q}\Bigl\{\frac{L}{\sigma}d(x)+\sum_{i=0}^k\frac{i+1}{2}\bigl[f(x_i)+\langle \nabla f(x_i),x-x_i\rangle\bigr]\Bigr\},\\
\text{(b)}\quad &\tau_k=\frac{2}{k+3},\qquad x_{k+1}=\tau_k z_k+(1-\tau_k)y_k,\\
\text{(c)}\quad &\hat x_{k+1}=V_Q\Bigl(z_k,\frac{\sigma}{L}\tau_k\nabla f(x_{k+1})\Bigr),\\
\text{(d)}\quad &y_{k+1}=\tau_k\hat x_{k+1}+(1-\tau_k)y_k.
\end{aligned}
\tag{5.6}
\end{equation}
\end{algorithm}
(depend on: "Definition 1.5.3.1", "Lemma 1.5.3.1")

\begin{proposition}\label{prop:5.7}
Let $Q=\Delta_n$ and let the prox-function be the entropy distance
\begin{equation}\label{eq:auto_Proposition_5_7_content_1}
d(x)=\ln n+\sum_{i=1}^n x^{(i)}\ln x^{(i)}.
\end{equation}
Then for $z\in\Delta_n$ and $g\in\mathbb{R}^n$, the mapping $V_Q(z,g)$ from Definition~5.6 has the explicit form
\begin{equation}\label{eq:5.7}
V_Q^{(i)}(z,g)
=
z^{(i)}e^{-g^{(i)}}\Bigl[\sum_{j=1}^n z^{(j)}e^{-g^{(j)}}\Bigr]^{-1},
\qquad i=1,\dots,n.
\tag{5.7}
\end{equation}
\end{proposition}
(depend on: "Definition 1.5.3.1", "Lemma 1.4.1.1")

proof:
\begin{proof}\label{proof:prop:5.7}
By definition,
\begin{equation}\label{eq:auto_Proposition_5_7_proof_1}
V_Q(z,g)=\arg\min_{x\in\Delta_n}\{\langle g,x-z\rangle+\xi(z,x)\}.
\end{equation}
For the entropy prox-function, the Bregman distance equals the Kullback--Leibler divergence:
\begin{equation}\label{eq:auto_Proposition_5_7_proof_2}
\xi(z,x)=\sum_{i=1}^n x^{(i)}\ln\frac{x^{(i)}}{z^{(i)}},
\end{equation}
up to an additive constant independent of $x$.
Therefore, the optimization becomes
\begin{equation}\label{eq:auto_Proposition_5_7_proof_3}
\min_{x\in\Delta_n}\ \sum_{i=1}^n\Bigl(g^{(i)}x^{(i)}+x^{(i)}\ln\frac{x^{(i)}}{z^{(i)}}\Bigr).
\end{equation}
Introducing a Lagrange multiplier $\lambda$ for $\sum_i x^{(i)}=1$ and differentiating gives
\begin{equation}\label{eq:auto_Proposition_5_7_proof_4}
g^{(i)}+\ln\frac{x^{(i)}}{z^{(i)}}+1=\lambda,\qquad i=1,\dots,n,
\end{equation}
hence $x^{(i)}=z^{(i)}e^{\lambda-1}e^{-g^{(i)}}$.
Enforcing $\sum_i x^{(i)}=1$ yields $e^{\lambda-1}=\bigl(\sum_{j=1}^n z^{(j)}e^{-g^{(j)}}\bigr)^{-1}$, and substituting back gives \eqref{eq:5.7}.
\end{proof}
